def _flash(request: Request, kind: str, message: str) -> None:
    request.session["flash"] = {"kind": kind, "message": message}


def _float_or_none(value: str | None):
    if value in (None, ""):
        return None
    normalized = str(value).strip().replace("R$", "").replace("\xa0", "").replace(" ", "")
    if "," in normalized:
        normalized = normalized.replace(".", "").replace(",", ".")
    return float(normalized)


def _int_or_none(value: str | None):
    if value in (None, ""):
        return None
    if isinstance(value, str):
        cleaned = value.strip().replace("\xa0", "").replace(" ", "")
        if re.fullmatch(r"-?\d{1,3}(\.\d{3})+", cleaned):
            cleaned = cleaned.replace(".", "")
        value = cleaned
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _positive_int(value: str | None, default: int = 1) -> int:
    parsed = _int_or_none(value)
    if parsed is None or parsed < 1:
        return default
    return parsed


def _backup_details(value: str | None) -> dict:
    if not value:
        return {}
    try:
        parsed = json.loads(value)
        return parsed if isinstance(parsed, dict) else {}
    except json.JSONDecodeError:
        return {}


def _format_storage_bytes(value: int | float | None) -> str:
    size = float(value or 0)
    units = ["B", "KB", "MB", "GB", "TB"]
    unit_index = 0
    while size >= 1024 and unit_index < len(units) - 1:
        size /= 1024
        unit_index += 1
    precision = 0 if unit_index == 0 else 2
    return f"{size:.{precision}f} {units[unit_index]}"


def _build_backup_storage_usage(repo: FarmRepository, live_usage: dict[str, int] | None = None) -> dict[str, object]:
    setting = repo.get_backup_automation_setting()
    has_snapshot = (
        getattr(setting, "last_storage_checked_at", None) is not None
        and getattr(setting, "last_storage_database_bytes", None) is not None
        and getattr(setting, "last_storage_files_bytes", None) is not None
    )
    summary = (
        live_usage
        if live_usage is not None
        else {
            "database_bytes": setting.last_storage_database_bytes,
            "files_bytes": setting.last_storage_files_bytes,
            "other_bytes": setting.last_storage_other_bytes,
        }
        if has_snapshot
        else repo.summarize_backup_storage_usage()
    )
    database_bytes = int(summary.get("database_bytes", 0) or 0)
    files_bytes = int(summary.get("files_bytes", 0) or 0)
    other_bytes = int(summary.get("other_bytes", 0) or 0)
    total_bytes = int(summary.get("total_bytes", 0) or 0) or database_bytes + files_bytes + other_bytes
    storage_limit_gb = max(1, int(getattr(setting, "storage_limit_gb", 1) or 1))
    limit_bytes = int(getattr(setting, "storage_limit_bytes", 0) or 0) or storage_limit_gb * 1024 * 1024 * 1024
    usage_ratio = (total_bytes / limit_bytes) if limit_bytes > 0 else 0.0
    usage_percent = min(usage_ratio * 100, 100.0)
    remaining_bytes = max(limit_bytes - total_bytes, 0)
    is_over_limit = total_bytes >= limit_bytes
    tone = "danger" if usage_ratio >= 0.9 else "warning" if usage_ratio >= 0.75 else "ok"
    return {
        "limit_bytes": limit_bytes,
        "database_bytes": database_bytes,
        "files_bytes": files_bytes,
        "other_bytes": other_bytes,
        "total_bytes": total_bytes,
        "remaining_bytes": remaining_bytes,
        "usage_percent": round(usage_percent, 2),
        "usage_ratio": usage_ratio,
        "is_over_limit": is_over_limit,
        "limit_label": _format_storage_bytes(limit_bytes),
        "limit_gb": storage_limit_gb,
        "limit_source": getattr(setting, "storage_limit_source", None) or "fallback",
        "plan_name": getattr(setting, "storage_plan_name", None),
        "limit_checked_at_label": format_app_datetime(getattr(setting, "last_storage_limit_checked_at", None)) if getattr(setting, "last_storage_limit_checked_at", None) else "",
        "limit_attempted_at_label": format_app_datetime(getattr(setting, "last_storage_limit_attempted_at", None)) if getattr(setting, "last_storage_limit_attempted_at", None) else "",
        "limit_error": getattr(setting, "last_storage_limit_error", None),
        "database_label": _format_storage_bytes(database_bytes),
        "files_label": _format_storage_bytes(files_bytes),
        "other_label": _format_storage_bytes(other_bytes),
        "total_label": _format_storage_bytes(total_bytes),
        "remaining_label": _format_storage_bytes(remaining_bytes),
        "tone": tone,
        "is_live": live_usage is not None or has_snapshot,
        "checked_at_label": format_app_datetime(getattr(setting, "last_storage_checked_at", None)) if has_snapshot else "",
    }


