def _pretty_geojson_file_bytes(geojson_text: str) -> bytes:
    try:
        obj = json.loads(geojson_text)
        return json.dumps(obj, ensure_ascii=False, indent=2).encode("utf-8")
    except (json.JSONDecodeError, TypeError):
        return (geojson_text or "").encode("utf-8")


def _persist_plot_geojson_attachment(
    repo: FarmRepository,
    plot: Plot,
    payload: bytes,
    filename: str,
    content_type: str = "application/geo+json",
) -> bool:
    if not payload or len(payload) > _MAX_ATTACHMENT_SIZE_BYTES:
        return False
    try:
        repo.db.add(
            PlotAttachment(
                plot_id=plot.id,
                filename=_clean_attachment_filename(filename),
                content_type=(content_type or "application/geo+json")[:120],
                file_data=payload,
            )
        )
        repo.db.commit()
        repo.db.refresh(plot)
        return True
    except Exception:
        repo.db.rollback()
        logging.getLogger(__name__).exception("Falha ao gravar anexo GeoJSON do setor %s", plot.id)
        return False


def _maybe_record_plot_boundary_attachments(
    repo: FarmRepository,
    plot: Plot,
    geometry: str | None,
    upload_payload: bytes | None,
    upload_filename: str | None,
    old_geometry: str | None,
    *,
    is_new_plot: bool,
) -> None:
    if not geometry or not str(geometry).strip():
        return
    if upload_payload and upload_filename:
        ok = _persist_plot_geojson_attachment(repo, plot, upload_payload, upload_filename, "application/geo+json")
        if not ok:
            logging.getLogger(__name__).warning("Anexo GeoJSON enviado pelo usuario nao foi persistido (setor %s)", plot.id)
        return
    old_n = normalize_geojson(old_geometry) if (old_geometry or "").strip() else None
    new_n = normalize_geojson(geometry) if geometry else None
    if not is_new_plot and old_n == new_n:
        return
    stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
    fn = f"perimetro-setor-{plot.id}-{stamp}.geojson"
    body = _pretty_geojson_file_bytes(geometry)
    ok = _persist_plot_geojson_attachment(repo, plot, body, fn, "application/geo+json")
    if not ok:
        logging.getLogger(__name__).warning("GeoJSON gerado automaticamente nao foi persistido (setor %s)", plot.id)


async def _request_attachments(request: Request, field_name: str = "attachments") -> list[UploadFile]:
    form = await request.form()
    uploads: list[UploadFile] = []
    for value in form.getlist(field_name):
        if isinstance(value, (UploadFile, StarletteUploadFile)) and getattr(value, "filename", None):
            uploads.append(value)
    return uploads


def _attachment_response(
    filename: str,
    content_type: str,
    payload: bytes | bytearray | memoryview | None,
) -> Response:
    body = _attachment_payload_bytes(payload)
    media = _safe_attachment_media_type(content_type)
    cd = _content_disposition_inline_filename(filename)
    return Response(
        content=body,
        media_type=media,
        headers={"Content-Disposition": cd},
    )


def _require_permission(request: Request, user: User, db: Session, code: str) -> RedirectResponse | None:
    if user_has_permission(db, user, code):
        return None
    _flash(request, "error", "Voce nao tem permissao para acessar este recurso.")
    return _redirect("/dashboard")


def _require_admin(request: Request, user: User, db: Session) -> RedirectResponse | None:
    return _require_permission(request, user, db, USERS_MANAGE)


def _require_super_admin(request: Request, user: User) -> RedirectResponse | None:
    if is_super_admin_email(user.email):
        if current_asaas_environment(get_settings()).is_production:
            path = request.url.path
            commercial = any(path == prefix or path.startswith(prefix + "/")
                             for prefix in ("/assinaturas", "/planos", "/organizacoes"))
            if commercial:
                verified_at = request.session.get("commercial_mfa_at", 0)
                if not verified_at or (request.method != "GET" and app_now().timestamp() - verified_at > 1800):
                    _flash(request, "error", "Entre novamente com o código de verificação para gerenciar assinaturas.")
                    return _redirect("/dashboard")
        return None
    _flash(request, "error", "Apenas o super administrador pode acessar este modulo.")
    return _redirect("/dashboard")


def _user_in_default_organization(user: User | None) -> bool:
    if not user:
        return False
    organization = getattr(user, "organization", None)
    return bool(organization and organization.slug == "sisfarm")


def _require_default_organization_backup_access(
    request: Request, user: User, db: Session
) -> RedirectResponse | None:
    if not _user_in_default_organization(user):
        _flash(request, "error", "Backups ficam disponiveis apenas na organizacao padrao SiSFarm.")
        return _redirect("/dashboard")
    return _require_permission(request, user, db, BACKUPS_MANAGE)


def _backup_access_json_denied(user: User, db: Session) -> JSONResponse | None:
    if not _user_in_default_organization(user):
        return JSONResponse(
            {"ok": False, "error": "Backups ficam disponiveis apenas na organizacao padrao SiSFarm."},
            status_code=403,
        )
    if user_has_permission(db, user, BACKUPS_MANAGE):
        return None
    return JSONResponse(
        {"ok": False, "error": "Voce nao tem permissao para acessar os backups."},
        status_code=403,
    )


def _organization_slug_from_name(name: str) -> str:
    normalized = (
        unicodedata.normalize("NFD", name.strip().lower())
        .encode("ascii", "ignore")
        .decode("ascii")
    )
    slug = "".join(char if char.isalnum() else "-" for char in normalized)
    slug = "-".join(part for part in slug.split("-") if part)
    return slug[:160] or "organizacao"


def _unique_organization_slug(db: Session, name: str) -> str:
    base_slug = _organization_slug_from_name(name)
    slug = base_slug
    suffix = 2
    while db.query(Organization.id).filter(Organization.slug == slug).first():
        suffix_text = f"-{suffix}"
        slug = f"{base_slug[: 180 - len(suffix_text)]}{suffix_text}"
        suffix += 1
    return slug


def _soil_payload(
    farm_id: int,
    plot_id: int,
    analysis_date: str,
    laboratory: str,
    ph: str | None,
    organic_matter: str | None,
    phosphorus: str | None,
    potassium: str | None,
    calcium: str | None,
    magnesium: str | None,
    aluminum: str | None,
    h_al: str | None,
    ctc: str | None,
    base_saturation: str | None,
    observations: str | None,
    pdf_filename: str | None,
    pdf_content_type: str | None,
    pdf_data: bytes | None,
    current_analysis: SoilAnalysis | None = None,
    laboratory_metadata: dict | None = None,
) -> dict:
    payload = {
        "farm_id": farm_id,
        "plot_id": plot_id,
        "analysis_date": analysis_date,
        "laboratory": laboratory,
        "ph": _float_or_none(ph),
        "organic_matter": _float_or_none(organic_matter),
        "phosphorus": _float_or_none(phosphorus),
        "potassium": _float_or_none(potassium),
        "calcium": _float_or_none(calcium),
        "magnesium": _float_or_none(magnesium),
        "aluminum": _float_or_none(aluminum),
        "h_al": _float_or_none(h_al),
        "ctc": _float_or_none(ctc),
        "base_saturation": _float_or_none(base_saturation),
        "observations": observations,
        "pdf_filename": pdf_filename if pdf_filename is not None else (current_analysis.pdf_filename if current_analysis else None),
        "pdf_content_type": pdf_content_type if pdf_content_type is not None else (current_analysis.pdf_content_type if current_analysis else None),
        "pdf_data": pdf_data if pdf_data is not None else (current_analysis.pdf_data if current_analysis else None),
    }
    payload["laboratory_metadata"] = json.dumps(laboratory_metadata, ensure_ascii=False) if laboratory_metadata else None
    calculation = dict(payload)
    if laboratory_metadata:
        for field, unit in laboratory_metadata["units"].items():
            if field not in SOIL_FIELDS:
                continue
            calculation[field] = canonical_value(field, payload[field], unit) if unit else None
        # The historical thresholds use organic matter in percent.
        if laboratory_metadata["units"]["organic_matter"] == "g/kg" and payload["organic_matter"] is not None:
            calculation["organic_matter"] = payload["organic_matter"] / 10
        elif calculation["organic_matter"] is not None:
            calculation["organic_matter"] /= 10
    payload.update(calculate_soil_recommendations(calculation))
    return payload


AGRONOMIC_PROFILE_COMPLETION_WEIGHTS = (
    ("culture", "cultura", 8),
    ("region", "região", 7),
    ("cultivar", "cultivar predominante", 8),
    ("production_system", "sistema de produção", 6),
    ("climate", "clima", 5),
    ("soil_type", "tipo de solo", 10),
    ("irrigation_system", "sistema de irrigação", 10),
    ("plant_spacing", "espaçamento entre plantas", 4),
    ("crop_stage", "fase atual da lavoura", 10),
    ("fertilizers_used", "insumos já utilizados", 8),
    ("common_pests", "pragas e doenças recorrentes", 6),
    ("target_productivity_sacks_per_ha", "meta de produtividade", 7),
    ("last_liming_date", "última calagem", 4),
    ("current_limitations", "limitações atuais", 7),
)


def _agronomic_profile_completion(profile: AgronomicProfile | None) -> tuple[int, list[str]]:
    if not profile:
        return 0, ["cadastre o Perfil Agronômico da fazenda"]
    total_weight = sum(weight for _, _, weight in AGRONOMIC_PROFILE_COMPLETION_WEIGHTS)
    completed_weight = sum(
        weight
        for field, _, weight in AGRONOMIC_PROFILE_COMPLETION_WEIGHTS
        if getattr(profile, field, None)
    )
    missing = [
        label
        for field, label, _ in AGRONOMIC_PROFILE_COMPLETION_WEIGHTS
        if not getattr(profile, field, None)
    ]
    return round(completed_weight * 100 / total_weight), missing


def _soil_ai_allowed_pages(db: Session, user: User) -> set[str]:
    entitlements = _entitlements_for(db, user)
    pages = {PAGE_INPUTS, PAGE_OPERATIONS, PAGE_AGENDA, PAGE_IRRIGATION}
    return {code for code in pages & permission_codes_for_user(db, user) if entitlements.module_allowed(code)}


def _soil_timed(stage, operation, func, *args, **kwargs):
    started = monotonic_time.perf_counter()
    try:
        return func(*args, **kwargs)
    finally:
        logging.getLogger("uvicorn.error").info(
            "soil_analysis operation=%s stage=%s duration_ms=%.1f",
            operation, stage, (monotonic_time.perf_counter() - started) * 1000,
        )


def _apply_soil_ai_recommendation(repo: FarmRepository, analysis: SoilAnalysis, user: User) -> SoilAnalysis:
    refreshed = _soil_timed("load_db", "recommendation", repo.get_soil_analysis, analysis.id) or analysis
    allowed_pages = _soil_timed("permissions_db", "recommendation", _soil_ai_allowed_pages, repo.db, user)
    ai_result = gerar_recomendacao_adubacao(repo.db, refreshed, allowed_pages)
    if ai_result.get("status") != "generated" and refreshed.ai_recommendation:
        return _soil_timed(
            "save_db", "recommendation", repo.update, refreshed,
            {"ai_status": "outdated" if refreshed.ai_status == "outdated" else ai_result["status"],
             "ai_error": ai_result.get("error")},
        )
    return _soil_timed(
        "save_db", "recommendation", repo.update, refreshed,
        {
            "ai_recommendation": ai_result.get("recommendation"),
            "ai_status": ai_result.get("status"),
            "ai_model": ai_result.get("model"),
            "ai_error": ai_result.get("error"),
            "ai_generated_at": ai_result.get("generated_at"),
        },
    )


def _soil_history_chart(analyses: list[SoilAnalysis]) -> str:
    ordered = list(reversed(sorted(analyses, key=lambda item: (item.analysis_date, item.id))))
    result = {"labels": [item.analysis_date.isoformat() for item in ordered]}
    for field in ("ph", "phosphorus", "potassium", "calcium", "magnesium", "base_saturation"):
        values = []
        for item in ordered:
            raw = getattr(item, field)
            metadata = parse_metadata(item.laboratory_metadata)
            unit = metadata.get("units", {}).get(field)
            # Historical records lack a reliable unit and cannot be compared quantitatively.
            if field == "ph":
                values.append(float(raw) if raw is not None else None)
            elif raw is None or not unit:
                values.append(None)
            else:
                values.append(canonical_value(field, raw, unit))
        result[field] = values
    return json.dumps(result)


