@router.post("/primeiros-passos")
def onboarding_action(
    request: Request, csrf_token: str = Form(...), farm_name: str = Form(""), location: str = Form(""),
    total_area: str = Form(""), season_start: str = Form(""), season_end: str = Form(""),
    db: Session = Depends(get_db), user: User = Depends(get_current_user_web),
):
    """Cria a primeira fazenda e a safra atual e ja ativa o contexto, liberando o sistema."""
    validate_csrf(request, csrf_token)
    if not user.organization_id or _onboarding_done(db, user):
        return _redirect("/dashboard")
    form = {"farm_name": farm_name, "location": location, "total_area": total_area, "season_start": season_start, "season_end": season_end}
    name, place = (farm_name or "").strip(), (location or "").strip()
    area = _parse_br_decimal(total_area)
    try:
        start, end = date.fromisoformat(season_start), date.fromisoformat(season_end)
    except ValueError:
        start = end = None
    error = None
    existing = _first_org_farm(db, user)
    if existing:  # ja tem fazenda: so falta a safra
        area = float(existing.total_area or 0) or 1.0
    elif not name or len(name) > 160:
        error = "Informe o nome da fazenda."
    elif not place or len(place) > 180:
        error = "Informe a cidade e o estado da fazenda."
    elif area is None or not 0 < area <= 1_000_000:
        error = "Informe a área total da fazenda em hectares."
    elif _farm_name_taken(db, user.organization_id, name):
        error = f"Já existe uma fazenda chamada {name}. Use outro nome."
    if not error and (not start or not end or end <= start):
        error = "Confira as datas da safra: o fim precisa ser depois do início."
    if not error and not existing:
        error = farm_limit_error(db, quota_write_entitlements(db, user.organization_id, today_in_app_timezone()), adding_farm=True, area_delta=Decimal(str(area)))
    if error:
        return _render_onboarding(request, db, user, get_csrf_token(request), form=form, error=error)
    repo = _repository(db)
    farm = existing or create_farm(repo, {"name": name, "location": place, "total_area": area, "organization_id": user.organization_id})
    season = create_crop_season(repo, {"farm_id": farm.id, "start_date": start.isoformat(), "end_date": end.isoformat(), "culture": "Cafe",
                                       "cultivated_area": area, "area_unit": "ha", "status": "ativa"})
    persist_user_context(request, db, user, farm.id, season.id)
    _flash(request, "success", f"Tudo pronto! {farm.name} e a {season.name} já estão ativas.")
    return _redirect("/dashboard")


@router.get("/dashboard")
def dashboard(
    request: Request,
    background_tasks: BackgroundTasks,
    rain_start_date: str | None = None,
    rain_end_date: str | None = None,
    irrigations_page: int = 1,
    rainfalls_page: int = 1,
    fertilizations_page: int = 1,
    incidents_page: int = 1,
    harvests_page: int = 1,
    forecast_page: int = 1,
    timeline_page: int = 1,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
    csrf_token: str = Depends(get_csrf_token),
):
    repo = _repository(db)
    scope = _global_scope_context(request, repo)
    rain_settings = _farm_rain_settings(db, scope["active_farm_id"])
    data = build_dashboard_context(
        repo,
        rain_settings=rain_settings,
        rain_start_date=_date_or_none(rain_start_date),
        rain_end_date=_date_or_none(rain_end_date),
        farm_id=scope["active_farm_id"],
        season=scope["active_season"],
        organization_id=scope.get("active_organization_id"),
        context_farm_ids=[farm.id for farm in scope.get("context_farms", [])],
        pages={
            "irrigations": _page_number(irrigations_page),
            "rainfalls": _page_number(rainfalls_page),
            "fertilizations": _page_number(fertilizations_page),
            "incidents": _page_number(incidents_page),
            "harvests": _page_number(harvests_page),
            "forecast": _page_number(forecast_page),
            "timeline": _page_number(timeline_page),
        },
    )
    overview = data.get("overview") or {}
    entitlements = _entitlements_for(db, user)
    allowed_pages = {code for code in permission_codes_for_user(db, user) if entitlements.module_allowed(code)}
    filter_dashboard_attention(overview, allowed_pages)
    dashboard_map_preview_url = None
    dashboard_map_geojson = data.get("map_geojson") or ""
    dashboard_map_has_geometry = False
    try:
        dashboard_map_payload = json.loads(dashboard_map_geojson or "{}")
        dashboard_map_has_geometry = bool(dashboard_map_payload.get("features"))
    except (TypeError, json.JSONDecodeError):
        dashboard_map_has_geometry = False
    dashboard_map_fingerprint_value = dashboard_map_fingerprint(dashboard_map_geojson)
    if dashboard_map_has_geometry and dashboard_map_fingerprint_value:
        dashboard_map_path = dashboard_map_preview_fs_path(dashboard_map_fingerprint_value)
        if dashboard_map_path.is_file() and dashboard_map_path.stat().st_size > 0:
            dashboard_map_preview_url = (
                f"/static/{dashboard_map_preview_relative_path(dashboard_map_fingerprint_value)}"
                f"?v={dashboard_map_fingerprint_value}"
            )
        elif background_tasks is not None:
            background_tasks.add_task(
                generate_dashboard_map_preview,
                dashboard_map_geojson,
                dashboard_map_fingerprint_value,
            )
    return templates.TemplateResponse(
        "dashboard.html",
        _base_context(
            request,
            user,
            csrf_token,
            "dashboard",
            onboarding_steps=_onboarding_steps(db, user),
            rain_filters={
                "start_date": rain_start_date or "",
                "end_date": rain_end_date or "",
            },
            dashboard_page_values={
                "irrigations_page": _page_number(irrigations_page),
                "rainfalls_page": _page_number(rainfalls_page),
                "fertilizations_page": _page_number(fertilizations_page),
                "incidents_page": _page_number(incidents_page),
                "harvests_page": _page_number(harvests_page),
                "forecast_page": _page_number(forecast_page),
                "timeline_page": _page_number(timeline_page),
            },
            dashboard_map_preview_url=dashboard_map_preview_url,
            rain_settings=rain_settings,
            dashboard_rain_records=[
                {
                    "d": record.rainfall_date.isoformat(),
                    "mm": float(record.millimeters or 0),
                    "src": (record.source or "").strip(),
                    "notes": (record.notes or "").strip()[:120],
                }
                for record in (repo.list_rainfalls(farm_id=scope["active_farm_id"]) if scope["active_farm_id"] else [])
                if record.rainfall_date
            ],
            dashboard_map_has_geometry=dashboard_map_has_geometry,
            _repo=repo,
            **data,
        ),
    )


def _dashboard_cost_scope(request: Request, repo: FarmRepository, user: User):
    scope = _global_scope_context(request, repo, user)
    farm_id, season = scope.get("active_farm_id"), scope.get("active_season")
    plots = [plot for plot in (season.plots if season else []) if plot.farm_id == farm_id]
    return farm_id, season, plots


@router.get("/api/dashboard/custos")
def dashboard_cost_tree(
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    from app.services.season_costs import build_cost_tree

    if not user_has_permission(db, user, PAGE_FINANCE):
        return JSONResponse({"status": "forbidden"}, status_code=403)
    repo = _repository(db)
    farm_id, season, plots = _dashboard_cost_scope(request, repo, user)
    if not farm_id or season is None:
        return JSONResponse({"status": "no_season"})
    if not plots:
        return JSONResponse({"status": "no_plots", "season": season.name})
    data = build_cost_tree(repo, farm_id=farm_id, season=season, plots=plots, today=today_in_app_timezone())
    data["can_edit"] = user_has_permission(db, user, WRITE_FINANCE)
    return JSONResponse(data)


@router.post("/api/dashboard/custos/classificar")
def dashboard_cost_classify(
    request: Request,
    csrf_token: str = Form(...),
    entry_key: str = Form(...),
    subgroup: str = Form(...),
    learn_key: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    from app.models.cost_classification import CostClassification
    import re

    from app.services.season_costs import SUB_INDEX, normalize

    validate_csrf(request, csrf_token)
    if not user_has_permission(db, user, WRITE_FINANCE):
        return JSONResponse({"status": "forbidden"}, status_code=403)
    if subgroup not in SUB_INDEX or not re.fullmatch(r"(fin|stock):\d+", entry_key or ""):
        return JSONResponse({"status": "invalid"}, status_code=400)
    repo = _repository(db)
    farm_id, _season, _plots = _dashboard_cost_scope(request, repo, user)
    if not farm_id:
        return JSONResponse({"status": "no_farm"}, status_code=400)
    row = db.query(CostClassification).filter(CostClassification.farm_id == farm_id, CostClassification.entry_key == entry_key).first()
    if row is None:
        row = CostClassification(farm_id=farm_id, entry_key=entry_key)
        db.add(row)
    row.group_code, row.subgroup_code = SUB_INDEX[subgroup][0], subgroup
    row.learn_key = normalize(learn_key)[:200] or None
    row.user_id = user.id
    db.commit()
    return JSONResponse({"status": "ok"})


@router.get("/api/dashboard/clima")
def dashboard_weather_forecast(
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    import time as time_module

    from app.services.weather_forecast import (
        CACHE_TTL_SECONDS, farm_coordinates, fetched_at_datetime, get_farm_forecast,
    )

    if not user_has_permission(db, user, "page.rainfall"):
        return JSONResponse({"status": "forbidden"}, status_code=403)
    repo = _repository(db)
    scope = _global_scope_context(request, repo, user)
    farm = scope.get("active_farm")
    if not farm:
        return JSONResponse({"status": "no_farm"})
    coords = farm_coordinates(farm)
    if not coords:
        return JSONResponse({"status": "no_coords", "farm": farm.name, "farm_id": farm.id})
    result = get_farm_forecast(coords[0], coords[1])
    result.update(farm=farm.name, farm_id=farm.id, coords_source=coords[2],
                  latitude=round(coords[0], 4), longitude=round(coords[1], 4))
    fetched = result.pop("fetched_at", None)
    if fetched is not None:
        result["updated_at"] = format_app_datetime(fetched_at_datetime(fetched), "%d/%m/%Y às %H:%M")
        result["next_refresh_seconds"] = max(60, int(CACHE_TTL_SECONDS - (time_module.time() - fetched)))
    return JSONResponse(result, headers={"Cache-Control": "no-store"})


@router.post("/api/dashboard/cotacao-cafe/sincronizar-navegador")
async def sync_browser_coffee_quotes_action(
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    del user
    payload = await request.json()
    validate_csrf(request, str(payload.get("csrf_token") or ""))
    raw_quotes = payload.get("quotes")
    if not isinstance(raw_quotes, list):
        return JSONResponse({"ok": False, "message": "Cotações inválidas."}, status_code=400)

    quotes: list[CoffeeQuote] = []
    for raw_quote in raw_quotes:
        if not isinstance(raw_quote, dict):
            continue
        quote_type = str(raw_quote.get("quote_type") or "").strip().lower()
        if quote_type not in {"arabica", "robusta"}:
            continue
        try:
            quote_date = date.fromisoformat(str(raw_quote.get("quote_date") or ""))
            price_brl = float(raw_quote.get("price_brl"))
        except (TypeError, ValueError):
            continue
        if price_brl <= 0:
            continue
        quotes.append(
            CoffeeQuote(
                quote_type=quote_type,
                quote_date=quote_date,
                price_brl=round(price_brl, 2),
                variation_day=None,
                variation_month=None,
                price_usd=None,
                source=CEPEA_SOURCE,
                source_url=CEPEA_WIDGET_URL,
                fetched_at=app_now(),
            )
        )
    if not quotes:
        return JSONResponse({"ok": False, "message": "Nenhuma cotação válida encontrada."}, status_code=400)

    repo = _repository(db)
    latest = persist_browser_cepea_quotes(repo, quotes)
    return JSONResponse(
        {
            "ok": True,
            "latest": {
                quote_type: {
                    "quote_date": quote.quote_date.isoformat(),
                    "price_brl": float(quote.price_brl or 0),
                    "variation_day": float(quote.variation_day) if quote.variation_day is not None else None,
                    "variation_month": float(quote.variation_month) if quote.variation_month is not None else None,
                }
                for quote_type, quote in latest.items()
                if quote
            },
        }
    )

