def _finance_transaction_source_label(source: str | None) -> str:
    normalized = (source or "").strip().lower()
    if normalized == "insumos":
        return "Compra de Insumos"
    if normalized == "suprimentos":
        return "Suprimentos"
    if normalized in {"patrimônio", "patrimonio"}:
        return "Patrimônio"
    if normalized in {"manutenção de patrimônio", "manutencao de patrimonio"}:
        return "Manutenção de Patrimônio"
    if normalized in {"comercialização", "comercializacao"}:
        return "Comercialização"
    return "Contas"


def _finance_transaction_origin_edit_url(transaction: FinanceTransaction) -> str:
    normalized = (transaction.source or "").strip().lower()
    if normalized == "insumos" and transaction.purchased_inputs:
        entry = sorted(transaction.purchased_inputs, key=lambda item: item.id)[0]
        item_type = entry.input_catalog.item_type if entry.input_catalog and entry.input_catalog.item_type in {"insumo_agricola", "combustivel"} else None
        return _redirect_with_query("/insumos/comprados", edit_id=entry.id, item_type=item_type)
    if normalized == "suprimentos" and transaction.purchased_inputs:
        entry = sorted(transaction.purchased_inputs, key=lambda item: item.id)[0]
        return _redirect_with_query("/insumos/suprimentos", farm_id=entry.farm_id, edit_id=entry.id)
    if normalized in {"patrimônio", "patrimonio"} and transaction.equipment_assets:
        asset = sorted(transaction.equipment_assets, key=lambda item: item.id)[0]
        return _redirect_with_query("/insumos/patrimonio", edit_id=asset.id)
    if normalized in {"manutenção de patrimônio", "manutencao de patrimonio"} and transaction.maintenance_records:
        maintenance = sorted(transaction.maintenance_records, key=lambda item: item.id)[0]
        return _redirect_with_query("/insumos/patrimonio/manutencoes", edit_id=maintenance.id)
    if normalized in {"comercialização", "comercializacao"} and transaction.commercializations:
        sale = sorted(transaction.commercializations, key=lambda item: item.id)[0]
        return _redirect_with_query("/producao/comercializacao", edit_id=sale.id)
    return f"/gestao-financeira/contas?finance_tab=transactions&transaction_edit_id={transaction.id}"


def _finance_accounts_set_default(repo: FarmRepository, farm_id: int, keep_id: int | None = None) -> None:
    for account in repo.list_finance_accounts(farm_id=farm_id):
        if keep_id is not None and account.id == keep_id:
            continue
        if account.is_default:
            account.is_default = False
            repo.db.add(account)


def _finance_credit_cards_set_default(repo: FarmRepository, farm_id: int, keep_id: int | None = None) -> None:
    for card in repo.list_finance_credit_cards(farm_id=farm_id):
        if keep_id is not None and card.id == keep_id:
            continue
        if card.is_default:
            card.is_default = False
            repo.db.add(card)


def _finance_card_order_payload_ids(payload: dict) -> list[int]:
    raw_ids = payload.get("ordered_ids")
    if not isinstance(raw_ids, list):
        raise ValueError("Ordem inválida.")
    ordered_ids: list[int] = []
    for raw_id in raw_ids:
        try:
            item_id = int(raw_id)
        except (TypeError, ValueError):
            raise ValueError("Ordem inválida.") from None
        if item_id not in ordered_ids:
            ordered_ids.append(item_id)
    return ordered_ids


def _finance_credit_card_invoice_reference_label(due_date: date | None) -> str:
    if not due_date:
        return "Sem vencimento definido"
    month_names = (
        "janeiro",
        "fevereiro",
        "março",
        "abril",
        "maio",
        "junho",
        "julho",
        "agosto",
        "setembro",
        "outubro",
        "novembro",
        "dezembro",
    )
    return f"{month_names[due_date.month - 1].capitalize()}/{due_date.year}"


def _build_finance_credit_card_overviews(
    cards: list[FinanceCreditCard],
    transactions: list[FinanceTransaction],
    *,
    today: date,
) -> dict[int, dict]:
    transactions_by_card: dict[int, list[FinanceTransaction]] = defaultdict(list)
    for transaction in transactions:
        if not transaction.credit_card_id:
            continue
        if (transaction.operation_type or "").strip().lower() != "despesa":
            continue
        transactions_by_card[int(transaction.credit_card_id)].append(transaction)

    overviews: dict[int, dict] = {}
    for card in cards:
        card_transactions = transactions_by_card.get(int(card.id), [])
        grouped_invoices: dict[str, dict] = {}
        open_total = 0.0
        overdue_total = 0.0
        due_today_total = 0.0
        paid_total = 0.0
        installments_total = 0
        open_installments = 0
        paid_installments = 0

        for transaction in card_transactions:
            for installment in sorted(
                transaction.installments or [],
                key=lambda item: (item.due_date or date.max, item.installment_number or 0, item.id or 0),
            ):
                amount = round(float(installment.amount or 0), 2)
                due_date = installment.due_date
                status = (installment.status or "pendente").strip().lower()
                is_paid = status == "pago"
                installments_total += 1
                invoice_key = due_date.isoformat() if due_date else f"undated-{transaction.id}-{installment.id}"
                invoice_group = grouped_invoices.setdefault(
                    invoice_key,
                    {
                        "reference_label": _finance_credit_card_invoice_reference_label(due_date),
                        "due_date": due_date,
                        "due_date_label": due_date.strftime("%d/%m/%Y") if due_date else "-",
                        "total": 0.0,
                        "open_total": 0.0,
                        "paid_total": 0.0,
                        "installment_count": 0,
                        "open_count": 0,
                        "paid_count": 0,
                        "line_items": [],
                    },
                )
                invoice_group["total"] = round(invoice_group["total"] + amount, 2)
                invoice_group["installment_count"] += 1
                installment_label = f"{int(installment.installment_number or 0)}/{int(transaction.installment_count or 0) or 1}"
                invoice_group["line_items"].append(
                    {
                        "transaction_id": transaction.id,
                        "installment_id": installment.id,
                        "launch_date": transaction.launch_date,
                        "launch_date_label": transaction.launch_date.strftime("%d/%m/%Y") if transaction.launch_date else "-",
                        "product_service": transaction.product_service,
                        "category": transaction.category or "-",
                        "source_label": _finance_transaction_source_label(transaction.source),
                        "amount": amount,
                        "status": "paid" if is_paid else "open",
                        "status_label": "Pago" if is_paid else "Em aberto",
                        "status_chip_class": "stock-movement-chip-entry" if is_paid else "stock-movement-chip-info",
                        "installment_label": installment_label,
                        "payment_method": transaction.payment_method or "-",
                    }
                )

                if is_paid:
                    paid_total = round(paid_total + amount, 2)
                    paid_installments += 1
                    invoice_group["paid_total"] = round(invoice_group["paid_total"] + amount, 2)
                    invoice_group["paid_count"] += 1
                    continue

                open_total = round(open_total + amount, 2)
                open_installments += 1
                invoice_group["open_total"] = round(invoice_group["open_total"] + amount, 2)
                invoice_group["open_count"] += 1
                if due_date and due_date < today:
                    overdue_total = round(overdue_total + amount, 2)
                elif due_date and due_date == today:
                    due_today_total = round(due_today_total + amount, 2)

        invoice_groups = sorted(
            grouped_invoices.values(),
            key=lambda row: (row["due_date"] or date.max, row["reference_label"]),
        )
        for invoice_group in invoice_groups:
            invoice_group["line_items"].sort(
                key=lambda item: (
                    item["launch_date"] or date.max,
                    item["transaction_id"],
                    item["installment_id"],
                )
            )
            due_date = invoice_group["due_date"]
            if invoice_group["open_total"] <= 0:
                status_key = "paid"
                status_label = "Pago"
            elif due_date and due_date < today:
                status_key = "overdue"
                status_label = "Atrasada"
            elif due_date and due_date == today:
                status_key = "today"
                status_label = "Vence hoje"
            else:
                status_key = "open"
                status_label = "Em aberto"
            invoice_group["status_key"] = status_key
            invoice_group["status_label"] = status_label
            invoice_group["status_chip_class"] = {
                "paid": "stock-movement-chip-entry",
                "overdue": "stock-movement-chip-output",
                "today": "stock-movement-chip-warning",
                "open": "stock-movement-chip-info",
            }.get(status_key, "stock-movement-chip-info")

        next_open_invoice = next((item for item in invoice_groups if item["open_total"] > 0), None)
        credit_limit = float(card.credit_limit) if card.credit_limit is not None else None
        available_limit = round(credit_limit - open_total, 2) if credit_limit is not None else None
        usage_percent = None
        if credit_limit and credit_limit > 0:
            usage_percent = max(0.0, min(round((open_total / credit_limit) * 100, 1), 100.0))

        overviews[int(card.id)] = {
            "open_total": open_total,
            "overdue_total": overdue_total,
            "due_today_total": due_today_total,
            "paid_total": paid_total,
            "credit_limit": credit_limit,
            "available_limit": available_limit,
            "usage_percent": usage_percent,
            "installments_total": installments_total,
            "open_installments": open_installments,
            "paid_installments": paid_installments,
            "transaction_count": len(card_transactions),
            "next_open_invoice": next_open_invoice,
            "invoice_groups": invoice_groups,
        }
    return overviews


def _save_finance_transaction_attachments(
    repo: FarmRepository,
    transaction: FinanceTransaction,
    attachments: list[tuple[str, str, bytes]],
) -> int:
    if not attachments:
        return 0
    repo.db.add_all(
        [
            FinanceTransactionAttachment(
                finance_transaction_id=transaction.id,
                filename=filename,
                content_type=content_type,
                file_data=payload,
            )
            for filename, content_type, payload in attachments
        ]
    )
    try:
        repo.db.commit()
    except Exception:
        repo.db.rollback()
        raise
    repo.db.refresh(transaction)
    return len(attachments)


def _finance_transaction_category_options(operation_type: str | None) -> list[str]:
    normalized = (operation_type or "").strip().lower()
    if normalized == "receita":
        return FINANCE_TRANSACTION_REVENUE_CATEGORIES
    return FINANCE_TRANSACTION_EXPENSE_CATEGORIES


def _purchase_input_category_options(item_type: str | None) -> list[str]:
    normalized = (item_type or "").strip().lower()
    return PURCHASE_INPUT_CATEGORY_OPTIONS_BY_TYPE.get(normalized, PURCHASE_INPUT_CATEGORY_OPTIONS_BY_TYPE["insumo_agricola"])


def _normalize_purchase_input_category_label(category: str | None) -> str:
    cleaned = _clean_text(category)
    if cleaned == "Feritlizantes":
        return "Fertilizantes"
    return cleaned


def _resolve_purchase_input_category(item_type: str | None, category: str | None) -> str:
    cleaned = _normalize_purchase_input_category_label(category)
    allowed = _purchase_input_category_options(item_type)
    if cleaned not in allowed:
        raise ValueError("Selecione uma categoria válida para o tipo de item informado.")
    return cleaned


def _purchase_input_category_profile(category: str | None) -> dict:
    normalized = _normalize_purchase_input_category_label(category)
    return PURCHASE_INPUT_CATEGORY_PROFILES.get(normalized or "") or PURCHASE_INPUT_CATEGORY_PROFILES["Outros Itens"]


def _purchase_input_all_units() -> list[str]:
    units: list[str] = []
    for profile in PURCHASE_INPUT_CATEGORY_PROFILES.values():
        for unit in profile.get("units") or []:
            if unit not in units:
                units.append(unit)
    return units


def _input_catalog_primary_unit_from_first_entry(repo: FarmRepository, catalog) -> str:
    catalog_unit = _clean_text(getattr(catalog, "default_unit", None))
    catalog_id = getattr(catalog, "id", None)
    if not catalog_id:
        return catalog_unit
    entries = [
        entry
        for entry in repo.list_purchased_inputs()
        if entry.input_id == catalog_id and _clean_text(entry.package_unit)
    ]
    if not entries:
        return catalog_unit
    entries.sort(key=lambda entry: (entry.purchase_date or date.max, entry.id or 0))
    return _clean_text(entries[0].package_unit) or catalog_unit


def _resolve_purchase_input_package_unit(
    category: str | None,
    package_unit: str | None,
    *,
    catalog_primary_unit: str | None = None,
    allow_any_known_unit: bool = False,
) -> str:
    cleaned = _clean_text(package_unit)
    profile = _purchase_input_category_profile(category)
    allowed = list(profile.get("units") or [])
    if allow_any_known_unit:
        for unit in _purchase_input_all_units():
            if unit not in allowed:
                allowed.append(unit)
    extra = _clean_text(catalog_primary_unit)
    if extra and extra not in allowed:
        allowed.append(extra)
    if cleaned not in allowed:
        raise ValueError("Selecione uma unidade compatível com a categoria informada.")
    return cleaned


def _validate_purchased_entry_package_unit(
    repo: FarmRepository,
    *,
    item_type: str,
    category: str,
    name: str,
    package_unit: str,
    package_unit_override: str | None,
) -> tuple[str, str, str, str]:
    """Resolve tipo de insumo, categoria e unidade da embalagem.

    Quando o produto já existe no catálogo, o tipo de insumo, a categoria e a
    unidade primária são SEMPRE puxados do cadastro original (identidade do
    produto). A unidade só pode ser alterada quando o usuário pede o override
    explícito (lápis ao lado do campo), caso em que o novo valor é validado e
    aceito como nova unidade primária.

    Retorna ``(item_type, category, package_unit, package_unit_override_flag)``.
    """

    existing = repo.get_input_catalog_by_normalized_name(_normalize_input_name(name))
    override = str(package_unit_override or "").strip().lower() in ("1", "true", "on", "yes")
    posted_unit = _clean_text(package_unit)

    if existing:
        resolved_item_type = (existing.item_type or item_type or "insumo_agricola").strip() or "insumo_agricola"
        resolved_category = _resolve_purchase_input_category(
            resolved_item_type,
            existing.category or category,
        )
        existing_unit = _input_catalog_primary_unit_from_first_entry(repo, existing)
        if override:
            raw_for_validation = posted_unit or existing_unit or ""
            validated = _resolve_purchase_input_package_unit(
                resolved_category,
                raw_for_validation,
                catalog_primary_unit=existing_unit,
                allow_any_known_unit=True,
            )
            return resolved_item_type, resolved_category, validated, "1"
        resolved_unit = existing_unit or _resolve_purchase_input_package_unit(
            resolved_category,
            posted_unit or "kg",
            catalog_primary_unit=existing_unit,
        )
        return resolved_item_type, resolved_category, resolved_unit, ""

    resolved_item_type = (item_type or "insumo_agricola").strip() or "insumo_agricola"
    resolved_category = _resolve_purchase_input_category(resolved_item_type, category)
    if not posted_unit:
        raise ValueError("Selecione uma unidade válida.")
    validated = _resolve_purchase_input_package_unit(
        resolved_category,
        posted_unit,
        catalog_primary_unit=None,
        allow_any_known_unit=False,
    )
    return resolved_item_type, resolved_category, validated, ""


def _parse_finance_transaction_amount(raw_value: str | None) -> float:
    try:
        normalized = str(raw_value or "0").strip().replace("R$", "").replace(" ", "")
        if "," in normalized:
            normalized = normalized.replace(".", "").replace(",", ".")
        amount = round(abs(float(normalized or 0)), 2)
    except (TypeError, ValueError):
        raise ValueError("Informe um valor válido para o lançamento.")
    if amount <= 0:
        raise ValueError("Informe um valor maior que zero para o lançamento.")
    return amount


def _resolve_finance_transaction_account(
    repo: FarmRepository,
    *,
    active_farm: Farm,
    account_id: str | None,
) -> FinanceAccount:
    resolved_id = int(account_id) if str(account_id or "").strip().isdigit() else None
    account = repo.get_finance_account(resolved_id) if resolved_id else None
    if not account:
        account = next((item for item in repo.list_finance_accounts(farm_id=active_farm.id) if item.is_default), None)
    if not account:
        raise ValueError("Selecione a conta de lançamento.")
    if account.farm_id != active_farm.id:
        raise ValueError("A conta selecionada não pertence à fazenda ativa.")
    return account


def _resolve_optional_finance_account(
    repo: FarmRepository,
    *,
    active_farm: Farm | None,
    account_id: str | int | None,
) -> FinanceAccount | None:
    if not active_farm:
        return None
    resolved_id = _int_or_none(account_id)
    if resolved_id:
        account = repo.get_finance_account(resolved_id)
        if not account or account.farm_id != active_farm.id:
            raise ValueError("A conta selecionada não pertence à fazenda ativa.")
        return account
    return next((item for item in repo.list_finance_accounts(farm_id=active_farm.id) if item.is_default), None)


def _is_credit_card_payment_method(payment_method: str | None) -> bool:
    normalized = (
        unicodedata.normalize("NFD", str(payment_method or ""))
        .encode("ascii", "ignore")
        .decode("ascii")
        .strip()
        .lower()
    )
    return normalized == "cartao de credito"


def _finance_date_with_clamped_day(year: int, month: int, day: int) -> date:
    return date(year, month, min(max(day, 1), calendar.monthrange(year, month)[1]))


def _finance_credit_card_due_date(reference_date: date, *, closing_day: int, due_day: int) -> date:
    closing_this_month = _finance_date_with_clamped_day(reference_date.year, reference_date.month, closing_day)
    if reference_date <= closing_this_month:
        cycle_closing = closing_this_month
    else:
        next_month_reference = _finance_add_months(reference_date.replace(day=1), 1)
        cycle_closing = _finance_date_with_clamped_day(
            next_month_reference.year,
            next_month_reference.month,
            closing_day,
        )
    due_month_offset = 0 if due_day > cycle_closing.day else 1
    due_reference = _finance_add_months(cycle_closing.replace(day=1), due_month_offset)
    return _finance_date_with_clamped_day(due_reference.year, due_reference.month, due_day)


def _resolve_optional_finance_credit_card(
    repo: FarmRepository,
    *,
    active_farm: Farm | None,
    credit_card_id: str | int | None,
    payment_method: str | None,
) -> FinanceCreditCard | None:
    if not active_farm or not _is_credit_card_payment_method(payment_method):
        return None
    resolved_id = _int_or_none(credit_card_id)
    if resolved_id:
        card = repo.get_finance_credit_card(resolved_id)
        if not card or card.farm_id != active_farm.id:
            raise ValueError("O cartão selecionado não pertence à fazenda ativa.")
        return card
    default_card = next((item for item in repo.list_finance_credit_cards(farm_id=active_farm.id) if item.is_default), None)
    if default_card:
        return default_card
    raise ValueError("Selecione o cartão de crédito utilizado na compra.")


def _finance_transaction_payload(
    repo: FarmRepository,
    *,
    active_farm: Farm,
    operation_type: str,
    launch_date: str,
    amount: str,
    finance_account_id: str | None,
    credit_card_id: str | int | None,
    payment_condition: str | None,
    installment_count: str | None,
    installment_frequency: str | None,
    first_installment_date: str | None,
    category: str,
    product_service: str,
    description: str | None,
    counterparty_name: str | None,
    document_number: str | None,
    payment_method: str | None,
    notes: str | None,
    plot_id: str | int | None = None,
    season_id: int | None = None,
) -> dict:
    normalized_type = (operation_type or "").strip().lower()
    if normalized_type not in {"despesa", "receita"}:
        raise ValueError("Selecione o tipo de operação financeira.")
    if not launch_date:
        raise ValueError("Informe a data do lançamento.")
    try:
        parsed_launch_date = date.fromisoformat(launch_date)
    except ValueError:
        raise ValueError("Informe uma data válida para o lançamento.")
    category_value = _clean_text(category)
    if category_value not in _finance_transaction_category_options(normalized_type):
        raise ValueError("Selecione uma categoria válida para o lançamento.")
    product_service_value = _clean_text(product_service)
    if not product_service_value:
        raise ValueError("Informe o produto ou serviço.")
    resolved_plot_id = _int_or_none(plot_id)
    if resolved_plot_id:
        plot = repo.get_plot(resolved_plot_id)
        if not plot or plot.farm_id != active_farm.id:
            raise ValueError("Selecione um setor pertencente à fazenda ativa.")
        if normalized_type != "despesa" or category_value not in FINANCE_TRANSACTION_OPERATIONAL_EXPENSE_CATEGORIES:
            raise ValueError("O vínculo a setor está disponível apenas para despesas operacionais.")
        if not season_id:
            raise ValueError("Selecione uma safra ativa antes de vincular a despesa a um setor.")
    account = _resolve_finance_transaction_account(repo, active_farm=active_farm, account_id=finance_account_id)
    credit_card = (
        _resolve_optional_finance_credit_card(
            repo,
            active_farm=active_farm,
            credit_card_id=credit_card_id,
            payment_method=payment_method,
        )
        if normalized_type == "despesa"
        else None
    )
    normalized_condition = (payment_condition or "a_vista").strip().lower()
    if normalized_condition not in {"a_vista", "a_prazo"}:
        raise ValueError(
            "Selecione uma condição de recebimento válida."
            if normalized_type == "receita"
            else "Selecione uma condição de pagamento válida."
        )
    resolved_installment_count = 1
    resolved_frequency = None
    resolved_first_installment_date = None
    if normalized_condition == "a_prazo":
        try:
            resolved_installment_count = int(str(installment_count or "").strip())
        except ValueError:
            raise ValueError(
                "Informe a quantidade de parcelas para recebimento a prazo."
                if normalized_type == "receita"
                else "Informe a quantidade de parcelas para pagamento a prazo."
            )
        if resolved_installment_count < 1:
            raise ValueError(
                "Para recebimento a prazo, informe ao menos 1 parcela."
                if normalized_type == "receita"
                else "Para pagamento a prazo, informe ao menos 1 parcela."
            )
        resolved_frequency = (installment_frequency or "").strip().lower()
        if resolved_frequency not in {"mensal", "anual"}:
            raise ValueError("Selecione a periodicidade das parcelas.")
        if not first_installment_date:
            raise ValueError("Informe a data da primeira parcela.")
        try:
            resolved_first_installment_date = date.fromisoformat(first_installment_date)
        except ValueError:
            raise ValueError("Informe uma data válida para a primeira parcela.")
    else:
        resolved_first_installment_date = None if credit_card else parsed_launch_date
    return {
        "farm_id": active_farm.id,
        "plot_id": resolved_plot_id,
        "season_id": season_id if resolved_plot_id else None,
        "finance_account_id": account.id,
        "credit_card_id": credit_card.id if credit_card else None,
        "credit_card": credit_card,
        "operation_type": normalized_type,
        "launch_date": parsed_launch_date,
        "amount": _parse_finance_transaction_amount(amount),
        "payment_condition": normalized_condition,
        "installment_count": resolved_installment_count,
        "installment_frequency": resolved_frequency,
        "first_installment_date": resolved_first_installment_date,
        "category": category_value,
        "product_service": product_service_value,
        "description": _clean_text(description),
        "counterparty_name": _clean_text(counterparty_name),
        "document_number": _clean_text(document_number),
        "payment_method": _clean_text(payment_method),
        "notes": _clean_text(notes),
    }


def _finance_add_months(base_date: date, months: int) -> date:
    year = base_date.year + ((base_date.month - 1 + months) // 12)
    month = ((base_date.month - 1 + months) % 12) + 1
    day = min(base_date.day, calendar.monthrange(year, month)[1])
    return date(year, month, day)


def _finance_add_years(base_date: date, years: int) -> date:
    target_year = base_date.year + years
    day = min(base_date.day, calendar.monthrange(target_year, base_date.month)[1])
    return date(target_year, base_date.month, day)


def _build_finance_transaction_installments(
    *,
    amount: float,
    payment_condition: str,
    payment_method: str | None = None,
    credit_card: FinanceCreditCard | None = None,
    reference_date: date | None = None,
    installment_count: int,
    installment_frequency: str | None,
    first_installment_date: date | None,
) -> list[dict]:
    is_credit_card_purchase = bool(credit_card) and _is_credit_card_payment_method(payment_method)
    if installment_count < 1:
        return []
    if payment_condition != "a_prazo" and not is_credit_card_purchase:
        return []
    effective_first_due = first_installment_date
    effective_frequency = installment_frequency or "mensal"
    effective_count = installment_count
    if is_credit_card_purchase:
        effective_first_due = effective_first_due or _finance_credit_card_due_date(
            reference_date or today_in_app_timezone(),
            closing_day=int(credit_card.closing_day or 1),
            due_day=int(credit_card.due_day or 1),
        )
        if payment_condition != "a_prazo":
            effective_count = 1
            effective_frequency = "mensal"
    if not effective_first_due:
        return []
    total_cents = int((Decimal(str(amount)) * 100).quantize(Decimal("1")))
    base_cents = total_cents // effective_count
    remainder = total_cents % effective_count
    installments: list[dict] = []
    for index in range(effective_count):
        current_cents = base_cents + (1 if index < remainder else 0)
        if effective_frequency == "anual":
            due_date = _finance_add_years(effective_first_due, index)
        else:
            due_date = _finance_add_months(effective_first_due, index)
        installments.append(
            {
                "installment_number": index + 1,
                "due_date": due_date,
                "amount": round(current_cents / 100, 2),
                "status": "pendente",
            }
        )
    return installments


def _reject_finance_schedule_change_if_installment_paid(
    transaction: FinanceTransaction,
    payload: dict,
) -> None:
    """Impede alterar tipo, valor, data do lançamento, condição ou cronograma via POST quando há parcela paga (além da UI)."""
    any_paid = any(
        (getattr(i, "status", None) or "").strip().lower() == "pago"
        for i in (transaction.installments or [])
    )
    if not any_paid:
        return
    if (payload["operation_type"] or "").strip().lower() != (transaction.operation_type or "").strip().lower():
        raise ValueError(
            "Com parcela já quitada, o tipo de operação não pode ser alterado. Estorne os pagamentos das parcelas antes."
        )
    tr_amt = Decimal(str(transaction.amount))
    pl_amt = Decimal(str(payload["amount"]))
    if tr_amt.quantize(Decimal("0.01")) != pl_amt.quantize(Decimal("0.01")):
        raise ValueError(
            "Com parcela já quitada, o valor não pode ser alterado. Estorne os pagamentos das parcelas antes."
        )
    if payload["launch_date"] != transaction.launch_date:
        raise ValueError(
            "Com parcela já quitada, a data do lançamento não pode ser alterada. Estorne os pagamentos das parcelas antes."
        )
    if (payload.get("payment_method") or "").strip() != (transaction.payment_method or "").strip():
        raise ValueError(
            "Com parcela já paga, a forma de pagamento ou recebimento não pode ser alterada. Estorne os pagamentos antes."
        )
    if payload.get("credit_card_id") != transaction.credit_card_id:
        raise ValueError(
            "Com parcela já paga, o cartão utilizado não pode ser alterado. Estorne os pagamentos antes."
        )
    prior_pc = (transaction.payment_condition or "a_vista").strip().lower()
    if payload["payment_condition"] != prior_pc:
        raise ValueError(
            "Com parcela já paga, a condição de pagamento não pode ser alterada. Estorne os pagamentos das parcelas antes."
        )
    if prior_pc != "a_prazo":
        return
    if payload["installment_count"] != transaction.installment_count:
        raise ValueError(
            "Com parcela já paga, a quantidade e o cronograma de parcelas não podem ser alterados. Estorne os pagamentos antes."
        )
    tr_freq = (transaction.installment_frequency or "mensal").strip().lower()
    pl_freq = (payload["installment_frequency"] or "mensal").strip().lower()
    if tr_freq != pl_freq:
        raise ValueError(
            "Com parcela já paga, a periodicidade das parcelas não pode ser alterada. Estorne os pagamentos antes."
        )
    tr_first = transaction.first_installment_date
    pl_first = payload["first_installment_date"]
    if tr_first != pl_first:
        raise ValueError(
            "Com parcela já paga, a data da primeira parcela não pode ser alterada. Estorne os pagamentos antes."
        )


def _snapshot_finance_installments_for_edit(transaction: FinanceTransaction) -> list[dict]:
    """Cópia dos dados de parcelas antes de recriar linhas (evita perder pagamento ao editar)."""
    out: list[dict] = []
    for inst in sorted(transaction.installments or [], key=lambda x: (x.installment_number or 0, x.id)):
        out.append(
            {
                "installment_number": inst.installment_number,
                "status": inst.status,
                "paid_at": inst.paid_at,
                "payment_notes": inst.payment_notes,
            }
        )
    return out


def _validate_installment_edit_against_prior(
    new_rows: list[dict],
    prior_snapshot: list[dict],
) -> None:
    """
    Impede remover parcelas já pagas ou 'apagar' parcelamento com histórico de pagamento
    (ex.: mudar para à vista) sem estornar antes — padrão em ERPs.
    """
    if not prior_snapshot:
        return
    any_paid = any((row.get("status") or "").strip().lower() == "pago" for row in prior_snapshot)
    if not new_rows:
        if any_paid:
            raise ValueError(
                "Não é possível alterar para à vista ou remover o parcelamento enquanto houver parcelas pagas. "
                "Estorne os pagamentos no extrato de contas a pagar ou mantenha o lançamento à prazo."
            )
        return
    new_nums = {row["installment_number"] for row in new_rows}
    for prev in prior_snapshot:
        if (prev.get("status") or "").strip().lower() != "pago":
            continue
        num = prev.get("installment_number")
        if num not in new_nums:
            raise ValueError(
                "A nova configuração remove parcelas que já estão pagas. "
                "Mantenha quantidade de parcelas suficiente para incluir todas as parcelas já quitadas ou estorne pagamentos antes."
            )


def _merge_paid_installment_state_into_rows(new_rows: list[dict], prior_snapshot: list[dict]) -> None:
    """Preserva status, data e observações de parcelas pagas quando o número da parcela ainda existe."""
    prior_by_num = {row["installment_number"]: row for row in prior_snapshot}
    for row in new_rows:
        prior = prior_by_num.get(row["installment_number"])
        if not prior:
            continue
        if (prior.get("status") or "").strip().lower() != "pago":
            continue
        row["status"] = "pago"
        row["paid_at"] = prior.get("paid_at")
        row["payment_notes"] = prior.get("payment_notes")


def _replace_finance_transaction_installments(
    repo: FarmRepository,
    transaction: FinanceTransaction,
    installment_rows: list[dict],
) -> None:
    for installment in list(transaction.installments or []):
        repo.delete(installment)
    for row in installment_rows:
        repo.create(
            FinanceTransactionInstallment(
                finance_transaction_id=transaction.id,
                installment_number=row["installment_number"],
                due_date=row["due_date"],
                amount=row["amount"],
                status=row["status"],
                paid_at=row.get("paid_at"),
                payment_notes=row.get("payment_notes"),
            )
        )


def _finance_payables_period_ui_mode(payables_status: str) -> str:
    """Modo do picker de período na aba A pagar: past | future | custom_only."""
    if payables_status == "open":
        return "future"
    if payables_status == "all":
        return "custom_only"
    return "past"


def _payables_redirect_url(request: Request) -> str:
    """URL atual sem payables_partial (redirect após POST de cancelar pagamento)."""
    items = [(k, v) for k, v in request.query_params.multi_items() if k != "payables_partial"]
    path = str(request.url.path)
    if not items:
        return path
    return f"{path}?{urlencode(items)}"


def _receivables_redirect_url(request: Request) -> str:
    """URL atual sem receivables_partial (redirect após POST de cancelar recebimento)."""
    items = [(k, v) for k, v in request.query_params.multi_items() if k != "receivables_partial"]
    path = str(request.url.path)
    if not items:
        return path
    return f"{path}?{urlencode(items)}"


FINANCE_ACCOUNTS_EXPORT_DROP_KEYS = frozenset(
    {
        "edit_id",
        "launch",
        "transaction_edit_id",
        "transaction_launch",
        "card_edit_id",
        "card_launch",
        "payables_partial",
        "receivables_partial",
        "transactions_page",
        "payables_page",
        "receivables_page",
    }
)


def _finance_accounts_export_query_string(request: Request) -> str:
    items = [(k, v) for k, v in request.query_params.multi_items() if k not in FINANCE_ACCOUNTS_EXPORT_DROP_KEYS]
    return urlencode(items, doseq=True)


def _ensure_finance_tab_in_url(url: str, finance_tab: str) -> str:
    parsed = urlparse(url)
    pairs = [(k, v) for k, v in parse_qsl(parsed.query, keep_blank_values=True) if k != "finance_tab"]
    pairs.append(("finance_tab", finance_tab))
    q = urlencode(pairs, doseq=True)
    return f"{parsed.path}?{q}" if q else parsed.path


def _finance_accounts_pagination_with_tab(pagination: dict, finance_tab: str) -> dict:
    return {
        **pagination,
        "first_url": _ensure_finance_tab_in_url(pagination["first_url"], finance_tab),
        "prev_url": _ensure_finance_tab_in_url(pagination["prev_url"], finance_tab),
        "next_url": _ensure_finance_tab_in_url(pagination["next_url"], finance_tab),
        "last_url": _ensure_finance_tab_in_url(pagination["last_url"], finance_tab),
    }


def _finance_transactions_period_bounds(request: Request) -> tuple[date | None, date | None, str, str, str]:
    """Intervalo por data de lançamento (filtro da aba Lançamentos). Vazio = sem filtro de período."""
    qp = request.query_params
    selected_range = (qp.get("transactions_schedule_range") or qp.get("schedule_range") or "").strip()
    raw_start = (qp.get("transactions_start_date") or qp.get("start_date") or "").strip()
    raw_end = (qp.get("transactions_end_date") or qp.get("end_date") or "").strip()
    today = today_in_app_timezone()
    if selected_range == "all":
        return None, None, "", "", "all"
    if not selected_range and not raw_start and not raw_end:
        return None, None, "", "", ""

    if selected_range == "current_month":
        month_end = date(today.year + (1 if today.month == 12 else 0), 1 if today.month == 12 else today.month + 1, 1) - timedelta(days=1)
        return date(today.year, today.month, 1), month_end, "", "", "current_month"
    if selected_range == "last_10_days":
        return today - timedelta(days=10), today, "", "", "last_10_days"
    if selected_range == "last_20_days":
        return today - timedelta(days=20), today, "", "", "last_20_days"
    if selected_range == "last_month":
        current_month_start = date(today.year, today.month, 1)
        previous_month_end = current_month_start - timedelta(days=1)
        previous_month_start = date(previous_month_end.year, previous_month_end.month, 1)
        return previous_month_start, previous_month_end, "", "", "last_month"
    if selected_range == "next_10_days":
        return today, today + timedelta(days=10), "", "", "next_10_days"
    if selected_range == "next_20_days":
        return today, today + timedelta(days=20), "", "", "next_20_days"
    if selected_range == "next_month":
        if today.month == 12:
            nm_start = date(today.year + 1, 1, 1)
        else:
            nm_start = date(today.year, today.month + 1, 1)
        nm_end = date(nm_start.year + (1 if nm_start.month == 12 else 0), 1 if nm_start.month == 12 else nm_start.month + 1, 1) - timedelta(days=1)
        return nm_start, nm_end, "", "", "next_month"

    user_start: date | None = None
    user_end: date | None = None
    if raw_start:
        try:
            user_start = date.fromisoformat(raw_start)
        except ValueError:
            raw_start = ""
    if raw_end:
        try:
            user_end = date.fromisoformat(raw_end)
        except ValueError:
            raw_end = ""
    if user_start and user_end and user_start > user_end:
        return None, None, "", "", "custom"
    return user_start, user_end, raw_start, raw_end, (selected_range or "custom")


def _filtered_finance_transactions_for_accounts(
    repo: FarmRepository,
    *,
    active_farm: Farm,
    request: Request,
    transactions: list,
    period_start: date | None,
    period_end: date | None,
) -> list:
    tx_search = (request.query_params.get("transactions_search") or "").strip()
    tx_op = (request.query_params.get("transactions_operation") or "").strip().lower()
    if tx_op not in {"", "receita", "despesa"}:
        tx_op = ""
    raw_acc = (request.query_params.get("transactions_account_id") or "").strip()
    tx_account_id: int | None = None
    if raw_acc:
        try:
            tx_account_id = int(raw_acc)
        except ValueError:
            tx_account_id = None
    valid_account_ids = {a.id for a in repo.list_finance_accounts(farm_id=active_farm.id)}
    if tx_account_id is not None and tx_account_id not in valid_account_ids:
        tx_account_id = None

    needle = _normalize_search_value(tx_search) if tx_search else ""
    filtered: list = []
    for transaction in transactions:
        if tx_op and (transaction.operation_type or "").strip().lower() != tx_op:
            continue
        if tx_account_id is not None and transaction.finance_account_id != tx_account_id:
            continue
        ld = transaction.launch_date
        if period_start and ld and ld < period_start:
            continue
        if period_end and ld and ld > period_end:
            continue
        if needle:
            searchable = " ".join(
                [
                    transaction.finance_account.account_name if transaction.finance_account else "",
                    transaction.credit_card.card_name if transaction.credit_card else "",
                    transaction.category or "",
                    transaction.product_service or "",
                    transaction.description or "",
                    transaction.source or "",
                    transaction.counterparty_name or "",
                    transaction.document_number or "",
                    ld.strftime("%d/%m/%Y") if ld else "",
                ]
            ).strip()
            if needle not in _normalize_search_value(searchable):
                continue
        filtered.append(transaction)
    return filtered


def _collect_finance_installment_rows(
    repo: FarmRepository,
    *,
    active_farm: Farm,
    request: Request,
    today: date,
    operation_type: str,
    search_param: str,
    status_param: str,
    range_prefix: str = "",
    paid_label: str = "Pago",
) -> tuple[list[dict], date | None, date | None, str, str, str, str, str]:
    """Lógica compartilhada entre as abas A pagar e A receber (filtros + linhas)."""
    transactions = repo.list_finance_transactions(farm_id=active_farm.id)
    filter_start_date, filter_end_date, raw_filter_start_date, raw_filter_end_date, selected_range = (
        _finance_installments_period_bounds(request, status_param=status_param, range_prefix=range_prefix)
    )
    search_term = (request.query_params.get(search_param) or "").strip()
    linked_transaction_id = _int_or_none(request.query_params.get("payables_transaction_id")) if operation_type == "despesa" else None
    selected_status = (request.query_params.get(status_param) or "").strip().lower()
    if selected_status not in {"", "open", "paid", "overdue", "all"}:
        selected_status = ""
    installment_rows: list[dict] = []
    for transaction in transactions:
        if linked_transaction_id and transaction.id != linked_transaction_id:
            continue
        if (transaction.operation_type or "").strip().lower() != operation_type:
            continue
        for installment in sorted(transaction.installments or [], key=lambda item: (item.due_date or date.max, item.installment_number or 0)):
            status = (installment.status or "pendente").strip().lower()
            due_date = installment.due_date
            installment_status = "open"
            installment_label = "Em aberto"
            if status == "pago":
                installment_status = "paid"
                installment_label = paid_label
            elif due_date and due_date < today:
                installment_status = "overdue"
                installment_label = "Atrasado"
            elif due_date and due_date == today:
                installment_status = "today"
                installment_label = "Vence hoje"
            if not selected_status and installment_status == "paid":
                continue
            if selected_status == "open" and installment_status not in {"open", "today"}:
                continue
            if selected_status == "paid" and installment_status != "paid":
                continue
            if selected_status == "overdue" and installment_status != "overdue":
                continue
            if filter_start_date and due_date and due_date < filter_start_date:
                continue
            if filter_end_date and due_date and due_date > filter_end_date:
                continue
            searchable = " ".join(
                [
                    transaction.finance_account.account_name if transaction.finance_account else "",
                    transaction.category or "",
                    transaction.product_service or "",
                    transaction.description or "",
                    installment.due_date.strftime("%d/%m/%Y") if installment.due_date else "",
                    installment_label,
                    _finance_transaction_source_label(transaction.source),
                ]
            ).strip()
            if search_term and _normalize_search_value(search_term) not in _normalize_search_value(searchable):
                continue
            installment_rows.append(
                {
                    "transaction": transaction,
                    "installment": installment,
                    "source_label": _finance_transaction_source_label(transaction.source),
                    "edit_url": _finance_transaction_origin_edit_url(transaction),
                    "status": installment_status,
                    "status_label": installment_label,
                    "status_chip_class": {
                        "paid": "stock-movement-chip-entry",
                        "overdue": "stock-movement-chip-output",
                        "today": "stock-movement-chip-warning",
                        "open": "stock-movement-chip-info",
                    }.get(installment_status, "stock-movement-chip-info"),
                    "row_kind": {
                        "paid": "entrada",
                        "overdue": "saida",
                        "today": "warning",
                        "open": "info",
                    }.get(installment_status, "info"),
                    "installment_label": f"{installment.installment_number}/{transaction.installment_count or 1}",
                    "search_text": searchable,
                }
            )
    installment_rows.sort(key=lambda row: (row["installment"].due_date or date.max, row["transaction"].id))
    return (
        installment_rows,
        filter_start_date,
        filter_end_date,
        raw_filter_start_date,
        raw_filter_end_date,
        selected_range,
        search_term,
        selected_status,
    )


def _finance_accounts_summary(
    transactions,
    *,
    today: date,
    account_balances: dict,
    card_overviews: dict,
    horizon_days: int = 30,
) -> dict:
    """Numeros do resumo da pagina Contas: saldo, a pagar/receber no horizonte e faturas de cartao."""
    horizon = today + timedelta(days=horizon_days)
    summary = {
        "balance_total": round(sum(float(value or 0) for value in account_balances.values()), 2),
        "payables_total": 0.0,
        "payables_overdue": 0,
        "receivables_total": 0.0,
        "receivables_overdue": 0,
        "receivables_next_due": None,
        "cards_open_total": 0.0,
        "cards_next_due": None,
        "horizon_days": horizon_days,
    }
    for transaction in transactions:
        operation = (transaction.operation_type or "").strip().lower()
        if operation not in {"despesa", "receita"}:
            continue
        if operation == "despesa" and transaction.credit_card_id:
            continue  # compras no cartao entram no total das faturas
        prefix = "payables" if operation == "despesa" else "receivables"
        for installment in transaction.installments or []:
            if (installment.status or "pendente").strip().lower() == "pago" or not installment.due_date:
                continue
            if installment.due_date > horizon:
                continue
            summary[f"{prefix}_total"] = round(summary[f"{prefix}_total"] + float(installment.amount or 0), 2)
            if installment.due_date < today:
                summary[f"{prefix}_overdue"] += 1
            elif prefix == "receivables" and (
                summary["receivables_next_due"] is None or installment.due_date < summary["receivables_next_due"]
            ):
                summary["receivables_next_due"] = installment.due_date
    for overview in card_overviews.values():
        summary["cards_open_total"] = round(summary["cards_open_total"] + float(overview.get("open_total") or 0), 2)
        next_invoice = overview.get("next_open_invoice")
        due = next_invoice.get("due_date") if next_invoice else None
        if due and (summary["cards_next_due"] is None or due < summary["cards_next_due"]):
            summary["cards_next_due"] = due
    return summary


def _safe_finance_accounts_return_url(candidate: str | None, *, default: str) -> str:
    """Aceita apenas path+query sob /gestao-financeira/contas (evita open redirect)."""
    raw = (candidate or "").strip()
    if not raw.startswith("/") or raw.startswith("//"):
        return default
    if len(raw) > 4096:
        return default
    path = raw.split("?", 1)[0].split("#", 1)[0]
    if ".." in path or not path.startswith("/gestao-financeira/contas"):
        return default
    return raw


