@router.get("/talhoes", include_in_schema=False)
@router.get("/setores")
def plots_page(
    request: Request,
    background_tasks: BackgroundTasks,
    q: str | None = None,
    sort: str = "name",
    edit_id: int | None = None,
    plot_map: int | None = None,
    selected_farm_id: int | None = None,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
    csrf_token: str = Depends(get_csrf_token),
):
    repo = _repository(db)
    scope = _global_scope_context(request, repo)
    context_farm_ids = [farm.id for farm in scope.get("context_farms", [])]
    farm_ids = _int_list(request.query_params.getlist("farm_id"))
    variety_ids = _int_list(request.query_params.getlist("variety_id"))
    if farm_ids:
        farm_ids = [farm_id for farm_id in farm_ids if farm_id in context_farm_ids]
    if not farm_ids and scope["active_farm_id"]:
        farm_ids = [scope["active_farm_id"]]
    elif not farm_ids:
        farm_ids = context_farm_ids
    if not variety_ids and scope["active_season"] and scope["active_season"].variety_id:
        variety_ids = [scope["active_season"].variety_id]
    edit_plot = repo.get_plot(edit_id) if edit_id else None
    if edit_plot and edit_plot.farm_id not in context_farm_ids:
        edit_plot = None
    open_plot_map_modal = bool(plot_map and edit_plot)
    farms, varieties = repo.list_plot_filter_options(
        farm_ids,
        variety_ids or None,
        organization_id=scope.get("active_organization_id"),
    )
    # Para o cadastro/edição do setor, a lista de variedades não deve ser limitada pelo filtro da página.
    # Caso contrário, o select "Variedade" fica preso à variedade da safra ativa (ex.: apenas 1 opção).
    form_varieties = repo.list_varieties(organization_id=scope.get("active_organization_id"))
    plots_list = repo.list_plots(search=q, farm_ids=farm_ids, variety_ids=variety_ids, sort=sort)
    plot_preview_ready: dict[int, bool] = {}
    plot_preview_fingerprint: dict[int, str] = {}
    for plot in plots_list:
        if not plot.boundary_geojson:
            continue
        plot_preview_fingerprint[plot.id] = hashlib.sha256(plot.boundary_geojson.encode("utf-8")).hexdigest()[:14]
        full_path = plot_preview_fs_path(plot.id)
        thumb_path = plot_preview_thumb_fs_path(plot.id)
        full_ok = full_path.is_file() and full_path.stat().st_size > 0
        thumb_ok = thumb_path.is_file() and thumb_path.stat().st_size > 0
        plot_preview_ready[plot.id] = full_ok and thumb_ok
        if not full_ok:
            farm_gj = _farm_boundary_for_plot_preview(plot)
            background_tasks.add_task(generate_plot_preview_image, plot.id, plot.boundary_geojson, farm_gj)
        elif not thumb_ok:
            background_tasks.add_task(ensure_plot_preview_thumb, plot.id)
    farm_preview_ready: dict[int, bool] = {}
    farm_preview_fingerprint: dict[int, str] = {}
    plots_farm_preview_urls: dict[str, str] = {}
    plots_db_hashes = cached_preview_hashes(db, [farm.id for farm in farms if farm.boundary_geojson])
    for farm in farms:
        if not farm.boundary_geojson:
            continue
        geo_hash = farm_geojson_hash(farm.boundary_geojson)
        farm_preview_fingerprint[farm.id] = geo_hash
        full_path = farm_preview_fs_path(farm.id)
        thumb_path = farm_preview_thumb_fs_path(farm.id)
        disk_ok = full_path.is_file() and full_path.stat().st_size > 0 and thumb_path.is_file() and thumb_path.stat().st_size > 0
        db_ok = bool(geo_hash and plots_db_hashes.get(farm.id) == geo_hash)
        farm_preview_ready[farm.id] = disk_ok or db_ok
        if not farm_preview_ready[farm.id]:
            background_tasks.add_task(schedule_farm_preview_generation, farm.id, farm.boundary_geojson)
        if farm_preview_ready[farm.id]:
            plots_farm_preview_urls[str(farm.id)] = (
                f"/fazendas/{farm.id}/preview.png?v={geo_hash}"
            )
    plot_farm_boundary_by_id: dict[str, object] = {}
    for farm in farms:
        if not farm.boundary_geojson:
            continue
        try:
            plot_farm_boundary_by_id[str(farm.id)] = json.loads(farm.boundary_geojson)
        except json.JSONDecodeError:
            pass
    plot_farm_boundaries_json = json.dumps(plot_farm_boundary_by_id)
    farm_ids_for_plot_context = [f.id for f in farms]
    plots_context_by_farm: dict[str, list[dict[str, object]]] = {}
    if farm_ids_for_plot_context:
        for plot in repo.list_plots_with_boundary_geojson(farm_ids=farm_ids_for_plot_context):
            if not plot.farm_id:
                continue
            try:
                gj_obj = json.loads(plot.boundary_geojson)
            except json.JSONDecodeError:
                continue
            plots_context_by_farm.setdefault(str(plot.farm_id), []).append({"id": plot.id, "geometry": gj_obj})
    plots_context_boundaries_json = json.dumps(plots_context_by_farm)
    edit_plot_geometry_json = "null"
    if edit_plot and edit_plot.boundary_geojson:
        try:
            edit_plot_geometry_json = json.dumps(json.loads(edit_plot.boundary_geojson))
        except json.JSONDecodeError:
            edit_plot_geometry_json = "null"
    google_maps_web_key = (get_settings().google_maps_api_key or "").strip()
    _plot_scope_season = scope.get("active_season")
    _plots_active_season_variety_id = (
        _plot_scope_season.variety_id if _plot_scope_season and _plot_scope_season.variety_id else None
    )
    plots_filters_active = _plots_page_filters_active(
        request,
        active_farm_id=scope["active_farm_id"],
        active_season_variety_id=_plots_active_season_variety_id,
        q=q,
        sort=sort,
    )
    plots_scope_active_farm_id = scope.get("active_farm_id")
    plots_farm_scope_locked = plots_scope_active_farm_id is not None
    plots_locked_farm_name = None
    if plots_farm_scope_locked:
        # A lista `farms` pode vir filtrada por safra/variedade e não incluir a fazenda do contexto.
        # Para evitar o fallback "Fazenda #id", busca sempre o nome real direto do repositório.
        _locked = repo.get_farm(plots_scope_active_farm_id)
        plots_locked_farm_name = _locked.name if _locked else f"Fazenda #{plots_scope_active_farm_id}"
    plots_field_q_filtered = bool((q or "").strip())
    plots_field_sort_filtered = sort != "name"
    plots_field_variety_filtered = _plots_variety_query_is_user_filter(request, _plots_active_season_variety_id)
    plot_wizard_groups = sorted({plot.group_name for plot in repo.list_plots(farm_ids=context_farm_ids or None) if plot.group_name}, key=str.lower) if context_farm_ids else []
    plot_wizard_season = scope.get("active_season")
    wizard_plots = repo.list_plots(farm_ids=context_farm_ids or None) if context_farm_ids else []
    scoped_farms_for_overview = [
        farm for farm in scope.get("context_farms", [])
        if not farm_ids or farm.id in farm_ids
    ]
    plots_overview = build_plots_overview_context(
        db,
        plots=plots_list,
        scoped_farms=scoped_farms_for_overview,
        active_season=plot_wizard_season,
        plot_preview_ready=plot_preview_ready,
        plot_preview_fingerprint=plot_preview_fingerprint,
        today=today_in_app_timezone(),
    )
    plot_wizard_data = {
        "today": date.today().isoformat(),
        "farms": {str(farm.id): farm.name for farm in scope.get("context_farms", [])},
        "farm_areas": {str(farm.id): float(farm.total_area or 0) for farm in scope.get("context_farms", [])},
        "colors": [list(color) for color in PLOT_COLORS],
        "used": wizard_color_context(wizard_plots),
        "varieties": {str(variety.id): variety.name for variety in form_varieties},
        "season": plot_wizard_season.name if plot_wizard_season and plot_wizard_season.status != "encerrada" else None,
        "edit": {"id": edit_plot.id, "name": edit_plot.name} if edit_plot else None,
    }
    return templates.TemplateResponse(
        "plots.html",
        _base_context(
            request,
            user,
            csrf_token,
            "plots",
            plots=plots_list,
            farms=farms,
            varieties=varieties,
            form_varieties=form_varieties,
            filters={"q": q or "", "farm_ids": farm_ids, "variety_ids": variety_ids, "sort": sort},
            plots_filters_active=plots_filters_active,
            plots_farm_scope_locked=plots_farm_scope_locked,
            plots_scope_active_farm_id=plots_scope_active_farm_id,
            plots_locked_farm_name=plots_locked_farm_name,
            plots_field_q_filtered=plots_field_q_filtered,
            plots_field_variety_filtered=plots_field_variety_filtered,
            plots_field_sort_filtered=plots_field_sort_filtered,
            plots_overview=plots_overview,
            edit_plot=edit_plot,
            plot_colors=PLOT_COLORS,
            plot_wizard_data=plot_wizard_data,
            plot_groups=plot_wizard_groups,
            soil_textures=SOIL_TEXTURES,
            plot_wizard_season=plot_wizard_season if plot_wizard_season and plot_wizard_season.status != "encerrada" else None,
            planting_end_reasons=PLANTING_END_REASONS,
            open_plot_map_modal=open_plot_map_modal,
            selected_farm_id=selected_farm_id or scope["active_farm_id"],
            plot_farm_boundaries_json=plot_farm_boundaries_json,
            plots_context_boundaries_json=plots_context_boundaries_json,
            edit_plot_geometry_json=edit_plot_geometry_json,
            google_maps_web_key=google_maps_web_key,
            plot_preview_ready=plot_preview_ready,
            plot_preview_fingerprint=plot_preview_fingerprint,
            farm_preview_ready=farm_preview_ready,
            farm_preview_fingerprint=farm_preview_fingerprint,
            plots_farm_preview_urls=plots_farm_preview_urls,
            filter_links=[
                {"farm_id": plot.farm_id, "variety_id": plot.variety_id}
                for plot in repo.list_plots(farm_ids=farm_ids, variety_ids=variety_ids or None)
                if plot.farm_id or plot.variety_id
            ],
            _repo=repo,
        ),
    )


def _create_variety_from_wizard(repo: FarmRepository, scope: dict, raw_name: str) -> int | None:
    """"+ Outra" no passo Plantio: reaproveita a variedade com o mesmo nome ou cria uma nova na organização."""
    name = " ".join((raw_name or "").split())[:120]
    if not name:
        return None
    org_id = scope.get("active_organization_id")
    for variety in repo.list_varieties(organization_id=org_id):
        if variety.name.strip().lower() == name.lower():
            return variety.id
    variety = create_variety(repo, {"organization_id": org_id, "name": name, "species": "Não informada", "maturation_cycle": "Não informado"})
    return variety.id


@router.get("/setores/{plot_id}/pronto")
def plot_done_page(plot_id: int, request: Request, db: Session = Depends(get_db), user: User = Depends(get_current_user_web),
                   csrf_token: str = Depends(get_csrf_token)):
    repo = _repository(db)
    scope = _global_scope_context(request, repo)
    plot = repo.get_plot(plot_id)
    if not plot or not _farm_matches_scope(plot.farm_id, scope):
        return _redirect("/setores")
    return templates.TemplateResponse(
        "plot_done.html",
        _base_context(request, user, csrf_token, "plots", _repo=repo, title="Setor criado", plot=plot,
                      season_name=request.query_params.get("safra")),
    )


def _apply_plot_wizard_fields(repo: FarmRepository, plot, farm, geometry, map_color, color_mode, group_name, soil_texture, *, is_new: bool,
                              field_reference: str | None = None, soil_report=None) -> None:
    """Cor no mapa, grupo, tipo de solo, referência no campo e laudo de solo vindos do assistente de setor."""
    if color_mode is None and map_color is None and group_name is None and soil_texture is None:
        return  # formulário antigo: não mexe
    if soil_report is not None and getattr(soil_report, "filename", None):
        payload = soil_report.file.read()
        if payload:
            repo.db.add(PlotAttachment(plot_id=plot.id, filename=f"Laudo de solo - {soil_report.filename}"[:255],
                                       content_type=soil_report.content_type or "application/octet-stream", file_data=payload))
            repo.db.commit()
    repo.update(plot, {"field_reference": " ".join((field_reference or "").split())[:160] or None})
    color = normalize_color(map_color) if color_mode in {"manual", "auto"} else None
    if not color and (is_new or color_mode == "auto" or not plot.map_color):
        others = [other for other in repo.list_plots(farm_ids=[farm.id]) if other.id != plot.id]
        color = pick_auto_color(others, geometry)
    repo.update(plot, {
        "map_color": color or plot.map_color,
        "group_name": normalize_group(group_name),
        "soil_texture": normalize_soil(soil_texture),
    })


def _include_plot_in_active_season(repo: FarmRepository, scope: dict, plot):
    """Coloca o setor na safra ativa do topo (mesma fazenda). Devolve a safra ou None."""
    season = repo.get_crop_season(scope.get("active_season_id")) if scope.get("active_season_id") else None
    if not season or season.farm_id != plot.farm_id or season.status == "encerrada":
        return None
    if plot not in season.plots:
        season.plots.append(plot)
        repo.db.commit()
        link_season_plantings(repo, season)
    return season


@router.post("/talhoes", include_in_schema=False)
@router.post("/setores")
def create_plot_action(
    request: Request,
    csrf_token: str = Form(...),
    name: str = Form(...),
    area_hectares: str = Form(...),
    farm_id: str | None = Form(None),
    planting_date: str | None = Form(None),
    plant_count: str | None = Form(None),
    spacing_row_meters: str | None = Form(None),
    spacing_plant_centimeters: str | None = Form(None),
    estimated_yield_sacks: str | None = Form(None),
    variety_id: str | None = Form(None),
    centroid_lat: str | None = Form(None),
    centroid_lng: str | None = Form(None),
    boundary_geojson: str | None = Form(None),
    boundary_geojson_file: UploadFile | None = File(None),
    irrigation_type: str | None = Form("none"),
    irrigation_line_count: str | None = Form(None),
    irrigation_line_length_meters: str | None = Form(None),
    drip_spacing_centimeters: str | None = Form(None),
    drip_liters_per_hour: str | None = Form(None),
    sprinkler_count: str | None = Form(None),
    sprinkler_liters_per_hour: str | None = Form(None),
    notes: str | None = Form(None),
    map_color: str | None = Form(None),
    color_mode: str | None = Form(None),
    group_name: str | None = Form(None),
    soil_texture: str | None = Form(None),
    include_in_season: str | None = Form(None),
    field_reference: str | None = Form(None),
    new_variety_name: str | None = Form(None),
    soil_report: UploadFile | None = File(None),
    return_to: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    validate_csrf(request, csrf_token)
    repo = _repository(db)
    scope = _global_scope_context(request, repo, user)
    try:
        parsed_area = _float_or_none(area_hectares)
    except ValueError:
        parsed_area = None
    if not parsed_area or parsed_area <= 0:
        _flash(request, "error", "Informe a área do setor em hectares (ex.: 5,4).")
        return _redirect("/setores")
    selected_farm_id = _int_or_none(farm_id)
    if not selected_farm_id:
        _flash(request, "error", "Selecione uma fazenda antes de salvar o setor.")
        return _redirect("/setores")
    selected_variety_id = _int_or_none(variety_id)
    if not selected_variety_id and (new_variety_name or "").strip():
        selected_variety_id = _create_variety_from_wizard(repo, scope, new_variety_name)
    if selected_variety_id:
        selected_variety = repo.get_variety(selected_variety_id)
        if not _variety_matches_scope(selected_variety, scope):
            _flash(request, "error", "A variedade selecionada nao pertence a organizacao atual.")
            return _redirect("/setores")
    farm = repo.get_farm(selected_farm_id)
    if not farm or not _farm_matches_scope(farm.id, scope):
        _flash(request, "error", "A fazenda selecionada nao foi encontrada.")
        return _redirect("/setores")
    farm_total_area = float(farm.total_area or 0)
    if farm_total_area > 0 and parsed_area > farm_total_area + 1e-6:
        area_fmt = f"{farm_total_area:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        _flash(
            request,
            "error",
            f"A área do setor não pode ser maior que a área da fazenda {farm.name} ({area_fmt} ha).",
        )
        return _redirect_with_query("/setores", selected_farm_id=selected_farm_id)
    if _plot_name_taken(db, farm.id, name):
        _flash(request, "error", f"Já existe um setor chamado {name.strip()} nesta fazenda. Use outro nome.")
        return _redirect_with_query("/setores", selected_farm_id=selected_farm_id)
    geometry, geometry_ok, upload_payload, upload_filename = _resolve_geojson(boundary_geojson_file, boundary_geojson)
    if boundary_geojson_file and boundary_geojson_file.filename and not geometry_ok:
        _flash(request, "error", "O arquivo GeoJSON do setor nao e valido.")
        return _redirect_with_query("/setores", selected_farm_id=selected_farm_id)
    if geometry and farm.boundary_geojson and geometry_outside_farm(geometry, farm.boundary_geojson):
        _flash(request, "error", f"O desenho do setor passa do perímetro da fazenda {farm.name}. Ajuste os pontos para ficarem dentro da divisa.")
        return _redirect_with_query("/setores", selected_farm_id=selected_farm_id)
    new_plot = create_plot(
        repo,
        _build_plot_payload(
            farm=farm,
            name=name,
            area_hectares=parsed_area,
            planting_date=planting_date,
            plant_count=_int_or_none(plant_count) or 0,
            spacing_row_meters=spacing_row_meters,
            spacing_plant_centimeters=spacing_plant_centimeters,
            estimated_yield_sacks=estimated_yield_sacks,
            variety_id=str(selected_variety_id) if selected_variety_id else None,
            centroid_lat=centroid_lat,
            centroid_lng=centroid_lng,
            boundary_geojson=geometry,
            notes=notes,
            irrigation_type=irrigation_type,
            irrigation_line_count=irrigation_line_count,
            irrigation_line_length_meters=irrigation_line_length_meters,
            drip_spacing_centimeters=drip_spacing_centimeters,
            drip_liters_per_hour=drip_liters_per_hour,
            sprinkler_count=sprinkler_count,
            sprinkler_liters_per_hour=sprinkler_liters_per_hour,
        ),
    )
    if geometry:
        try:
            farm_gj = farm.boundary_geojson if farm.boundary_geojson else None
            generate_plot_preview_image(new_plot.id, geometry, farm_gj)
        except Exception:
            logging.getLogger(__name__).exception("Falha ao gerar imagem de satelite do setor %s", new_plot.id)
    _maybe_record_plot_boundary_attachments(
        repo,
        new_plot,
        geometry,
        upload_payload,
        upload_filename,
        None,
        is_new_plot=True,
    )
    _apply_plot_wizard_fields(repo, new_plot, farm, geometry, map_color, color_mode, group_name, soil_texture, is_new=True,
                              field_reference=field_reference, soil_report=soil_report)
    joined_season = _include_plot_in_active_season(repo, scope, new_plot) if include_in_season else None
    if return_to and return_to.startswith("safra"):
        _flash(request, "success", f"Setor {new_plot.name} criado." + (f" Já entrou na {joined_season.name}." if joined_season else ""))
    if return_to == "safra":
        return _redirect(f"/safras?novo=1&setor={new_plot.id}")
    if return_to and return_to.startswith("safra:") and return_to[6:].isdigit():
        return _redirect(f"/safras?edit_id={int(return_to[6:])}&rascunho=1&setor={new_plot.id}")
    return _redirect_with_query(f"/setores/{new_plot.id}/pronto", safra=joined_season.name if joined_season else None)


@router.post("/talhoes/{plot_id}/editar", include_in_schema=False)
@router.post("/setores/{plot_id}/renovar-plantio")
def renew_plot_planting_action(
    plot_id: int,
    request: Request,
    csrf_token: str = Form(...),
    ended_on: str = Form(...),
    end_reason: str = Form(...),
    culture: str | None = Form("Café"),
    variety_id: str | None = Form(None),
    planting_date: str | None = Form(None),
    plant_count: str | None = Form(None),
    spacing_row_meters: str | None = Form(None),
    spacing_plant_centimeters: str | None = Form(None),
    estimated_yield_sacks: str | None = Form(None),
    notes: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    validate_csrf(request, csrf_token)
    repo = _repository(db)
    scope = _global_scope_context(request, repo, user)
    plot = repo.get_plot(plot_id)
    if not plot or not _farm_matches_scope(plot.farm_id, scope):
        _flash(request, "error", "Setor nao encontrado.")
        return _redirect("/setores")
    back = f"/setores?edit_id={plot.id}"
    selected_variety_id = _int_or_none(variety_id)
    if selected_variety_id and not _variety_matches_scope(repo.get_variety(selected_variety_id), scope):
        _flash(request, "error", "A variedade selecionada nao pertence a organizacao atual.")
        return _redirect(back)
    try:
        parsed_end = date.fromisoformat(ended_on)
        parsed_planting = date.fromisoformat(planting_date) if planting_date else None
    except ValueError:
        _flash(request, "error", "Informe datas válidas para o encerramento e o novo plantio.")
        return _redirect(back)
    try:
        renew_planting(repo, plot, ended_on=parsed_end, end_reason=end_reason, new={
            "culture": culture, "variety_id": selected_variety_id, "planting_date": parsed_planting,
            "plant_count": _int_or_none(plant_count), "spacing_row_meters": _float_or_none(spacing_row_meters),
            "spacing_plant_meters": _meters_from_cm(spacing_plant_centimeters), "estimated_yield_sacks": _float_or_none(estimated_yield_sacks),
            "notes": notes,
        })
    except PlantingRenewalError as exc:
        db.rollback()
        _flash(request, "error", str(exc))
        return _redirect(back)
    _flash(request, "success", "Plantio renovado. O plantio anterior foi guardado no histórico do setor.")
    return _redirect(back)


