@router.get("/fazendas/{farm_id}/geomapa.kml")
def download_farm_geometry_kml(
    farm_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    """Baixa o perimetro salvo da fazenda, sem consultar servicos externos."""
    farm = _repository(db).get_farm(farm_id)
    if not farm or (user.organization_id and farm.organization_id != user.organization_id):
        raise HTTPException(status_code=404, detail="Fazenda nao encontrada.")
    if not (farm.boundary_geojson or "").strip():
        raise HTTPException(status_code=404, detail="Esta fazenda ainda nao possui um perimetro salvo.")
    try:
        content = farm_boundary_to_kml(farm.name, farm.boundary_geojson)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    filename = quote(f"geomapa-{farm.name or 'fazenda'}.kml")
    return Response(
        content=content,
        media_type="application/vnd.google-earth.kml+xml; charset=utf-8",
        headers={"Content-Disposition": f"attachment; filename*=UTF-8''{filename}"},
    )


@router.post("/fazendas")
async def create_farm_action(
    request: Request,
    csrf_token: str = Form(...),
    name: str = Form(...),
    location: str = Form(...),
    total_area: float = Form(...),
    car_registration_number: str | None = Form(None),
    ccir_number: str | None = Form(None),
    itr_registration_number: str | None = Form(None),
    property_registration_number: str | None = Form(None),
    registry_office: str | None = Form(None),
    boundary_geojson: str | None = Form(None),
    boundary_geojson_file: UploadFile | None = File(None),
    notes: str | None = Form(None),
    redirect_to: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    validate_csrf(request, csrf_token)
    name = (name or "").strip()
    if _farm_name_taken(db, user.organization_id, name):
        _flash(request, "error", f"Já existe uma fazenda chamada {name}. Use outro nome.")
        return _redirect("/setores") if redirect_to == "/setores" else _redirect("/fazendas")
    try:
        car_number = normalize_car_number(car_registration_number) if (car_registration_number or "").strip() else None
    except CarPublicLookupError as exc:
        _flash(request, "error", str(exc))
        return _redirect("/setores") if redirect_to == "/setores" else _redirect("/fazendas")
    try:
        attachment_payloads = _read_attachments(await _request_attachments(request))
    except ValueError as exc:
        _flash(request, "error", str(exc))
        return _redirect("/setores") if redirect_to == "/setores" else _redirect("/fazendas")
    geometry, geometry_ok, _, _ = _resolve_geojson(boundary_geojson_file, boundary_geojson)
    if boundary_geojson_file and boundary_geojson_file.filename and not geometry_ok:
        _flash(request, "error", "O arquivo GeoJSON da fazenda nao e valido.")
        return _redirect("/setores") if redirect_to == "/setores" else _redirect("/fazendas")
    limit_error = farm_limit_error(db, quota_write_entitlements(db, user.organization_id, today_in_app_timezone()), adding_farm=True, area_delta=Decimal(str(total_area or 0)))
    if limit_error:
        _flash(request, "error", limit_error)
        return _redirect("/setores") if redirect_to == "/setores" else _redirect("/fazendas")
    farm = create_farm(
        _repository(db),
        {
            "name": name,
            "location": location,
            "total_area": total_area,
            "car_registration_number": car_number,
            "ccir_number": (ccir_number or "").strip() or None,
            "itr_registration_number": (itr_registration_number or "").strip() or None,
            "property_registration_number": (property_registration_number or "").strip() or None,
            "registry_office": (registry_office or "").strip() or None,
            "boundary_geojson": geometry,
            "notes": notes,
            "organization_id": user.organization_id,
        },
    )
    try:
        saved_attachments = _save_farm_attachments(_repository(db), farm, attachment_payloads)
    except Exception:
        _flash(request, "error", "A fazenda foi cadastrada, mas nao foi possivel gravar os anexos agora.")
        return _redirect("/setores") if redirect_to == "/setores" else _redirect("/fazendas")
    message = "Fazenda cadastrada com sucesso."
    if saved_attachments:
        message += f" {saved_attachments} anexo(s) salvo(s)."
    _flash(request, "success", message)
    response = _redirect_with_query("/setores", selected_farm_id=farm.id) if redirect_to == "/setores" else _redirect("/fazendas")
    if geometry:
        response.background = BackgroundTask(schedule_farm_preview_generation, farm.id, geometry)
    return response


@router.post("/fazendas/{farm_id}/editar")
async def update_farm_action(
    farm_id: int,
    request: Request,
    csrf_token: str = Form(...),
    name: str = Form(...),
    location: str = Form(...),
    total_area: float = Form(...),
    car_registration_number: str | None = Form(None),
    ccir_number: str | None = Form(None),
    itr_registration_number: str | None = Form(None),
    property_registration_number: str | None = Form(None),
    registry_office: str | None = Form(None),
    boundary_geojson: str | None = Form(None),
    boundary_geojson_file: UploadFile | None = File(None),
    notes: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    validate_csrf(request, csrf_token)
    repo = _repository(db)
    farm = repo.get_farm(farm_id)
    if not farm or (user.organization_id and farm.organization_id != user.organization_id):
        _flash(request, "error", "Fazenda nao encontrada.")
        return _redirect("/fazendas")
    name = (name or "").strip()
    if _farm_name_taken(db, farm.organization_id, name, exclude_id=farm.id):
        _flash(request, "error", f"Já existe uma fazenda chamada {name}. Use outro nome.")
        return _redirect_with_query("/fazendas", edit_id=farm_id)
    try:
        car_number = normalize_car_number(car_registration_number) if (car_registration_number or "").strip() else None
    except CarPublicLookupError as exc:
        _flash(request, "error", str(exc))
        return _redirect_with_query("/fazendas", edit_id=farm_id)
    try:
        attachment_payloads = _read_attachments(await _request_attachments(request))
    except ValueError as exc:
        _flash(request, "error", str(exc))
        return _redirect_with_query("/fazendas", edit_id=farm_id)
    previous_geojson = (farm.boundary_geojson or "").strip()
    geometry, geometry_ok, _, _ = _resolve_geojson(boundary_geojson_file, boundary_geojson, farm.boundary_geojson)
    if boundary_geojson_file and boundary_geojson_file.filename and not geometry_ok:
        _flash(request, "error", "O arquivo GeoJSON da fazenda nao e valido.")
        return _redirect_with_query("/fazendas", edit_id=farm_id)
    entitlements = quota_write_entitlements(db, farm.organization_id, today_in_app_timezone())
    db.refresh(farm)
    if farm.organization_id != user.organization_id and user.organization_id:
        _flash(request, "error", "Fazenda não encontrada.")
        return _redirect("/fazendas")
    limit_error = None if farm.operations_paused else farm_limit_error(
        db, entitlements, adding_farm=False, area_delta=Decimal(str(total_area or 0)) - Decimal(farm.total_area or 0),
    )
    if limit_error:
        _flash(request, "error", limit_error)
        return _redirect_with_query("/fazendas", edit_id=farm_id)
    update_farm(
        repo,
        farm,
        {
            "name": name,
            "location": location,
            "total_area": total_area,
            "car_registration_number": car_number,
            "ccir_number": (ccir_number or "").strip() or None,
            "itr_registration_number": (itr_registration_number or "").strip() or None,
            "property_registration_number": (property_registration_number or "").strip() or None,
            "registry_office": (registry_office or "").strip() or None,
            "boundary_geojson": geometry,
            "notes": notes,
        },
    )
    old_hash = farm_geojson_hash(previous_geojson)
    new_hash = farm_geojson_hash(geometry)
    should_regen_preview = False
    if geometry:
        if new_hash != old_hash:
            should_regen_preview = True
        else:
            db_hashes = cached_preview_hashes(db, [farm.id])
            disk_ok = farm_preview_fs_path(farm.id).is_file() and farm_preview_thumb_fs_path(farm.id).is_file()
            if not disk_ok and db_hashes.get(farm.id) != new_hash:
                should_regen_preview = True
    else:
        if previous_geojson:
            remove_farm_preview_image(farm.id)
    try:
        saved_attachments = _save_farm_attachments(repo, farm, attachment_payloads)
    except Exception:
        _flash(request, "error", "As alteracoes foram salvas, mas nao foi possivel incluir os novos anexos.")
        return _redirect_with_query("/fazendas", edit_id=farm_id)
    message = "Fazenda atualizada com sucesso."
    if saved_attachments:
        message += f" {saved_attachments} novo(s) anexo(s) adicionado(s)."
    _flash(request, "success", message)
    response = _redirect(f"/fazendas/{farm.id}")
    if should_regen_preview and geometry:
        response.background = BackgroundTask(schedule_farm_preview_generation, farm.id, geometry)
    return response


