@router.post("/fazendas/{farm_id}/geometria")
def update_farm_geometry_only(
    farm_id: int,
    request: Request,
    csrf_token: str = Form(...),
    boundary_geojson: str = Form(...),
    redirect_to: str | None = Form(None),
    apply_polygon_area: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    validate_csrf(request, csrf_token)
    target = redirect_to if (redirect_to and redirect_to.startswith("/fazendas")) else "/fazendas"
    repo = _repository(db)
    farm = repo.get_farm(farm_id)
    if not farm or (user.organization_id and farm.organization_id != user.organization_id):
        _flash(request, "error", "Fazenda nao encontrada.")
        return _redirect("/fazendas")
    normalized = normalize_geojson(boundary_geojson)
    if not normalized:
        _flash(request, "error", "A geometria enviada nao e valida.")
        return _redirect(target)
    update_payload: dict[str, object] = {"boundary_geojson": normalized}
    if str(apply_polygon_area or "").strip() == "1":
        poly_area = calculate_geojson_area_hectares(normalized)
        if poly_area and poly_area > 0:
            new_area = round(float(poly_area), 2)
            entitlements = quota_write_entitlements(db, farm.organization_id, today_in_app_timezone())
            limit_error = None if farm.operations_paused else farm_limit_error(
                db, entitlements, adding_farm=False, area_delta=Decimal(str(new_area)) - Decimal(farm.total_area or 0),
            )
            if limit_error:
                _flash(request, "error", limit_error)
                return _redirect(target)
            update_payload["total_area"] = new_area
    old_hash = farm_geojson_hash(farm.boundary_geojson)
    new_hash = farm_geojson_hash(normalized)
    repo.update(farm, update_payload)
    _flash(
        request,
        "success",
        "Geometria e área da fazenda atualizadas." if "total_area" in update_payload else "Geometria da fazenda atualizada.",
    )
    response = _redirect(target)
    if new_hash != old_hash or not farm_preview_fs_path(farm.id).is_file():
        response.background = BackgroundTask(schedule_farm_preview_generation, farm.id, normalized)
    return response


@router.post("/fazendas/{farm_id}/regularizacao")
def farm_operations_status_action(
    farm_id: int, request: Request, csrf_token: str = Form(...), action: str = Form(...),
    redirect_to: str | None = Form(None),
    db: Session = Depends(get_db), user: User = Depends(get_current_user_web),
):
    validate_csrf(request, csrf_token)
    denied = _require_permission(request, user, db, write_permission_for_page(PAGE_PRODUCTIVE_UNIT))
    if denied:
        return denied
    target = redirect_to if (redirect_to and redirect_to.startswith("/fazendas")) else "/fazendas"
    entitlements = quota_write_entitlements(db, user.organization_id, today_in_app_timezone())
    farm = db.query(Farm).filter_by(id=farm_id, organization_id=user.organization_id).with_for_update().first()
    if not farm or action not in {"pause", "resume"}:
        raise HTTPException(status_code=404, detail="Fazenda ou ação não encontrada.")
    if action == "resume" and farm.operations_paused:
        error = farm_limit_error(db, entitlements, adding_farm=True, area_delta=Decimal(farm.total_area or 0))
        if error:
            _flash(request, "error", error)
            return _redirect(target)
    farm.operations_paused = action == "pause"
    db.commit()
    _flash(request, "success", "Fazenda disponível para consulta." if farm.operations_paused else "Operações da fazenda reativadas.")
    return _redirect(target)


