@router.get("/organizacoes")
def organizations_page(
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
    csrf_token: str = Depends(get_csrf_token),
):
    denied = _require_super_admin(request, user)
    if denied:
        return denied
    repo = _repository(db)
    organizations = [item for item in repo.list_organizations() if item.archived_at is None]
    users = repo.list_users()
    farms = repo.list_farms()
    organization_stats = {
        organization.id: {
            "users": sum(1 for item in users if item.organization_id == organization.id),
            "farms": sum(1 for item in farms if item.organization_id == organization.id),
        }
        for organization in organizations
    }
    billing_by_organization = {item.organization_id: item for item in db.query(OrganizationBilling).all()}
    users_by_id = {item.id: item for item in users}
    primary_users = {
        org.id: users_by_id.get(org.primary_user_id)
        if users_by_id.get(org.primary_user_id) and users_by_id[org.primary_user_id].organization_id == org.id else None
        for org in organizations
    }
    signup_suggestions = {}
    grants = (db.query(OrganizationAccessGrant)
              .filter(OrganizationAccessGrant.organization_id.in_([org.id for org in organizations]),
                      OrganizationAccessGrant.reason == "teste_gratis",
                      OrganizationAccessGrant.created_by_user_id.isnot(None)).all())
    for grant in grants:
        suggested = users_by_id.get(grant.created_by_user_id)
        if suggested and suggested.is_active and suggested.organization_id == grant.organization_id:
            signup_suggestions.setdefault(grant.organization_id, set()).add(suggested.id)
    signup_suggestions = {org_id: users_by_id[next(iter(ids))] for org_id, ids in signup_suggestions.items() if len(ids) == 1}
    responsible_history = {}
    events = (db.query(AuditLog).filter(AuditLog.event_type == "comercial.organizacao.definir_responsavel",
                                        AuditLog.organization_id.in_([org.id for org in organizations]))
              .order_by(AuditLog.created_at.desc(), AuditLog.id.desc()).all())
    for event in events:
        history = responsible_history.setdefault(event.organization_id, [])
        if len(history) >= 5:
            continue
        try:
            details = json.loads(event.metadata_json or "{}")
        except (TypeError, ValueError):
            details = {}
        history.append({"date": event.created_at, "actor": event.actor_email,
                        "old": details.get("anterior"), "new": details.get("novo")})
    return templates.TemplateResponse(
        "organizations.html",
        _base_context(
            request,
            user,
            csrf_token,
            "organizations",
            title="Organizações",
            organizations=organizations,
            organization_stats=organization_stats,
            billing_by_organization=billing_by_organization,
            primary_users=primary_users,
            signup_suggestions=signup_suggestions,
            responsible_history=responsible_history,
            users=users,
            farms=farms,
            _repo=repo,
        ),
    )


@router.get("/organizacoes/avaliacoes-pezinho")
def whatsapp_surveys_page(
    request: Request, inicio: date | None = Query(None), fim: date | None = Query(None),
    organizacao: int | None = Query(None, gt=0), pagina: int = Query(1, ge=1),
    db: Session = Depends(get_db), user: User = Depends(get_current_user_web),
    csrf_token: str = Depends(get_csrf_token),
):
    denied = _require_super_admin(request, user)
    if denied:
        return denied
    if inicio and fim and inicio > fim:
        raise HTTPException(status_code=400, detail="A data inicial deve ser anterior à data final.")
    query = (db.query(WhatsAppSurvey, WhatsAppLink, Organization)
             .join(WhatsAppLink, WhatsAppSurvey.link_id == WhatsAppLink.id)
             .outerjoin(Organization, WhatsAppLink.organization_id == Organization.id))
    if inicio:
        query = query.filter(WhatsAppSurvey.created_at >= datetime.combine(inicio, time.min, tzinfo=get_app_timezone()).astimezone(timezone.utc))
    if fim and fim < date.max:
        query = query.filter(WhatsAppSurvey.created_at < datetime.combine(fim + timedelta(days=1), time.min, tzinfo=get_app_timezone()).astimezone(timezone.utc))
    if organizacao:
        query = query.filter(WhatsAppLink.organization_id == organizacao)
    counts = {"good": 0, "fair": 0, "bad": 0, "unrated": 0, "pending": 0, "unavailable": 0, "sending": 0}
    for survey_status, rating, count in query.with_entities(WhatsAppSurvey.status, WhatsAppSurvey.rating, func.count(WhatsAppSurvey.id)).group_by(WhatsAppSurvey.status, WhatsAppSurvey.rating).all():
        key = rating if survey_status == "answered" else survey_status
        if key in counts:
            counts[key] += count
    total = query.count()
    page_size = 25
    pages = max(1, (total + page_size - 1) // page_size)
    pagina = min(pagina, pages)
    rows = query.order_by(WhatsAppSurvey.created_at.desc(), WhatsAppSurvey.id.desc()).offset((pagina - 1) * page_size).limit(page_size).all()
    comments = {comment.survey_id: comment for comment in db.query(WhatsAppSurveyComment).filter(
        WhatsAppSurveyComment.survey_id.in_([row[0].id for row in rows]),
        WhatsAppSurveyComment.status == "answered").all()} if rows else {}
    organizations = db.query(Organization).order_by(Organization.name, Organization.id).all()
    params = {key: str(value) for key, value in {"inicio": inicio, "fim": fim, "organizacao": organizacao}.items() if value is not None}
    return templates.TemplateResponse("whatsapp_surveys.html", _base_context(
        request, user, csrf_token, "whatsapp_surveys", title="Avaliações do Pezinho",
        rows=rows, comments=comments, counts=counts, total=total, pagina=pagina, pages=pages, filters=params,
        organizations=organizations, query_string=urlencode(params), _repo=_repository(db)))


@router.get("/assinaturas")
def subscriptions_page(
    request: Request, organizacao: int | None = Query(None),
    db: Session = Depends(get_db), user: User = Depends(get_current_user_web), csrf_token: str = Depends(get_csrf_token),
):
    denied = _require_super_admin(request, user)
    if denied:
        return denied
    repo = _repository(db)
    organizations = repo.list_organizations()
    portfolio = build_subscription_portfolio(db, organizations, today_in_app_timezone())
    organization = next((item for item in organizations if item.id == organizacao), None) if organizacao is not None else None
    if organizacao is not None and not organization:
        raise HTTPException(status_code=404, detail="Organização não encontrada")
    billing = None
    current = {}
    migrations = {}
    previous = defaultdict(list)
    payments = defaultdict(list)
    if organization:
        billing = db.query(OrganizationBilling).filter_by(organization_id=organization.id).first()
        subscriptions = db.query(OrganizationSubscription).filter_by(organization_id=organization.id).order_by(OrganizationSubscription.id.desc()).all()
        for item in subscriptions:
            if item.is_current:
                current[organization.id] = item
            else:
                previous[organization.id].append(item)
        migration = db.query(OrganizationCardMigration).filter_by(organization_id=organization.id, is_open=True, environment=asaas_env_name()).first()
        if migration:
            migrations[organization.id] = migration
        ids = [item.id for item in subscriptions]
        if ids:
            for payment in db.query(OrganizationSubscriptionPayment).filter(OrganizationSubscriptionPayment.subscription_id.in_(ids)).order_by(OrganizationSubscriptionPayment.due_date.desc(), OrganizationSubscriptionPayment.id.desc()).all():
                payments[payment.subscription_id].append(payment)
    return templates.TemplateResponse("subscriptions.html", _base_context(
        request, user, csrf_token, "subscriptions", title="Assinaturas", organizations=organizations,
        organization=organization, billing=billing, subscriptions_by_organization=current,
        card_migrations_by_organization=migrations, previous_subscriptions_by_organization=previous,
        subscription_payments=payments, portfolio=portfolio, situation_labels=SITUATION_LABELS,
        available_plans=active_plans(db), plan_prices_of=plan_prices, today_iso=today_in_app_timezone().isoformat(),
        selected_row=next((row for row in portfolio.rows if organization and row.organization.id == organization.id), None),
        saved_card=_saved_card_charge(db, organization.id) if organization else None,
        asaas_config_error=asaas_configuration_error(get_settings()), asaas_webhook_ready=bool((get_settings().asaas_webhook_token or '').strip()),
        access_grants=db.query(OrganizationAccessGrant).filter_by(organization_id=organization.id).order_by(OrganizationAccessGrant.id.desc()).all() if organization else [],
        active_access_grant=active_grant(db, organization.id, today_in_app_timezone()) if organization else None,
        grant_reasons=GRANT_REASONS, grant_max_iso=(today_in_app_timezone() + timedelta(days=MAX_GRANT_DAYS)).isoformat(),
        grant_default_iso=default_grant_end(today_in_app_timezone()).isoformat(), grant_status_label=grant_status_label,
        grant_expiring=is_expiring_soon, today=today_in_app_timezone(), _repo=repo,
    ))


def _plan_form_fields(form) -> dict:
    return {
        "name": form.get("name"), "description": form.get("description"),
        "price_monthly": form.get("price_monthly"), "price_quarterly": form.get("price_quarterly"),
        "price_semiannual": form.get("price_semiannual"), "price_yearly": form.get("price_yearly"),
        "max_farms": form.get("max_farms"), "max_users": form.get("max_users"), "max_hectares": form.get("max_hectares"),
        "modules": form.getlist("modules"), "trial_days": form.get("trial_days"),
        "display_order": form.get("display_order"), "is_featured": form.get("is_featured"), "icon": form.get("icon"),
    }


@router.get("/planos")
def subscription_plans_page(
    request: Request, db: Session = Depends(get_db), user: User = Depends(get_current_user_web), csrf_token: str = Depends(get_csrf_token),
):
    denied = _require_super_admin(request, user)
    if denied:
        return denied
    plans = db.query(SubscriptionPlan).order_by(SubscriptionPlan.display_order, SubscriptionPlan.name, SubscriptionPlan.code, SubscriptionPlan.version.desc()).all()
    stats = {plan.id: {"total": 0, "current": 0, "mrr": Decimal("0.00")} for plan in plans}
    for subscription in db.query(OrganizationSubscription).filter(OrganizationSubscription.plan_id.isnot(None)).all():
        entry = stats.get(subscription.plan_id)
        if not entry:
            continue
        entry["total"] += 1
        if subscription.is_current:
            entry["current"] += 1
            if subscription.asaas_status == "ACTIVE":
                entry["mrr"] += monthly_amount(subscription)
    families: dict[str, list[SubscriptionPlan]] = {}
    for plan in plans:
        families.setdefault(plan.code, []).append(plan)
    for versions in families.values():
        versions.sort(key=lambda item: item.version, reverse=True)
    status_rank = {"ativo": 0, "rascunho": 1, "arquivado": 2}
    ordered = sorted(families.values(), key=lambda versions: (min(status_rank[item.status] for item in versions), versions[0].display_order, versions[0].name.lower()))
    return templates.TemplateResponse("subscription_plans.html", _base_context(
        request, user, csrf_token, "subscription_plans", title="Planos", plan_families=ordered, plan_stats=stats,
        plan_modules_catalog=PLAN_MODULES, plan_status_labels=PLAN_STATUSES, plan_modules_of=plan_modules,
        plan_prices_of=plan_prices, _repo=_repository(db),
    ))


