                    [Paragraph("MOVIMENTAÇÕES", meta_label_style), Paragraph(movement_label, meta_value_style)],
                    [Paragraph("INSUMO", meta_label_style), Paragraph("Filtrado" if selected_input_id else "Todos", meta_value_style)],
