def _rainfall_history_dataset(
    request: Request,
    repo: FarmRepository,
    *,
    flash_invalid: bool,
) -> dict:
    """Listagem de pluviometria: fazenda ativa, período (safra + filtro) e busca."""
    scope = _global_scope_context(request, repo)
    farm_scope_id = _active_farm_id(request)
    start_date, end_date, filter_start_str, filter_end_str = _schedule_filter_date_bounds(
        request, scope["active_season"], flash_invalid=flash_invalid
    )
    selected_rainfall_range = (
        _fertilization_filter_range_preset(
            request.query_params.get("schedule_range"),
            filter_start_str,
            filter_end_str,
        )
        if _period_filter_explicit_in_query(request)
        else ""
    )
    search_q = (request.query_params.get("search") or "").strip() or None
    rainfalls = repo.list_rainfalls(
        farm_id=farm_scope_id,
        start_date=start_date,
        end_date=end_date,
    )
    if search_q:
        query_norm = _normalize_search_value(search_q)
        rainfalls = [
            item
            for item in rainfalls
            if query_norm
            in _normalize_search_value(
                f"{item.farm.name if item.farm else ''} "
                f"{item.rainfall_date or ''} "
                f"{item.millimeters or ''} "
                f"{item.source or ''} "
                f"{item.notes or ''}"
            )
        ]
    rainfalls = _sort_collection_desc(
        rainfalls,
        lambda item: item.rainfall_date,
        lambda item: item.id,
    )
    return {
        "scope": scope,
        "farm_scope_id": farm_scope_id,
        "filter_start_str": filter_start_str,
        "filter_end_str": filter_end_str,
        "selected_rainfall_range": selected_rainfall_range,
        "search_q": search_q,
        "rainfalls_filtered": rainfalls,
    }


@router.get("/pluviometria")
def rainfall_page(
    request: Request,
    edit_id: int | None = None,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
    csrf_token: str = Depends(get_csrf_token),
):
    repo = _repository(db)
    data = _rainfall_history_dataset(request, repo, flash_invalid=True)
    scope = data["scope"]
    filter_start_str = data["filter_start_str"]
    filter_end_str = data["filter_end_str"]
    selected_rainfall_range = data["selected_rainfall_range"]
    search_q = data["search_q"]
    rainfalls = data["rainfalls_filtered"]

    rainfall_filter_clear_url = _url_with_query(
        request,
        start_date=None,
        end_date=None,
        schedule_range=None,
        rainfalls_page=None,
        search=None,
        edit_id=None,
    )
    rainfall_after_edit_close_url = _url_with_query(request, edit_id=None)

    rainfalls_pagination = _paginate_collection(request, rainfalls, "rainfalls_page")
    rainfall_edit_urls = {
        item.id: _url_with_query(request, edit_id=item.id) for item in rainfalls_pagination["items"]
    }
    rainfall_filters_active = bool(
        _period_filter_explicit_in_query(request) or bool(search_q)
    )
    return templates.TemplateResponse(
        "rainfall.html",
        _base_context(
            request,
            user,
            csrf_token,
            "rainfall",
            _repo=repo,
            rainfalls=rainfalls_pagination["items"],
            rainfalls_pagination=rainfalls_pagination,
            rainfall_filter_start_date=filter_start_str or None,
            rainfall_filter_end_date=filter_end_str or None,
            rainfall_filter_clear_url=rainfall_filter_clear_url,
            rainfall_after_edit_close_url=rainfall_after_edit_close_url,
            selected_rainfall_range=selected_rainfall_range,
            rainfall_filters_active=rainfall_filters_active,
            rainfall_edit_urls=rainfall_edit_urls,
            edit_rainfall=repo.get_rainfall(edit_id) if edit_id else None,
        ),
    )


RAIN_SETTINGS_DEFAULTS = {
    "heavy_rain_mm": 30.0,
    "rainy_day_mm": 1.0,
    "alert_registered": True,
    "alert_forecast": True,
    "notify_dashboard": True,
    "notify_bell": True,
    "average_since_year": None,
}


def _farm_rain_settings(db: Session, farm_id: int | None) -> dict:
    """Configuracoes de chuva da fazenda (valores padrao quando ainda nao foram salvas)."""
    settings = dict(RAIN_SETTINGS_DEFAULTS)
    if not farm_id:
        return settings
    row = db.query(FarmRainSettings).filter(FarmRainSettings.farm_id == farm_id).first()
    if row:
        settings.update(
            heavy_rain_mm=float(row.heavy_rain_mm or 30),
            rainy_day_mm=float(row.rainy_day_mm or 0),
            alert_registered=bool(row.alert_registered),
            alert_forecast=bool(row.alert_forecast),
            notify_dashboard=bool(row.notify_dashboard),
            notify_bell=bool(row.notify_bell),
            average_since_year=row.average_since_year,
        )
    return settings


@router.post("/pluviometria/configuracoes")
def save_rain_settings_action(
    request: Request,
    csrf_token: str = Form(...),
    heavy_rain_mm: float = Form(30),
    rainy_day_mm: float = Form(1),
    alert_registered: str | None = Form(None),
    alert_forecast: str | None = Form(None),
    notify_dashboard: str | None = Form(None),
    notify_bell: str | None = Form(None),
    average_since_year: str | None = Form(None),
    redirect_to: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    del user
    validate_csrf(request, csrf_token)
    repo = _repository(db)
    scope, denied = _launch_scope_or_redirect(request, repo, "/pluviometria", require_season=False)
    if denied:
        return denied
    farm_id = scope["active_farm_id"]
    row = db.query(FarmRainSettings).filter(FarmRainSettings.farm_id == farm_id).first()
    if row is None:
        row = FarmRainSettings(farm_id=farm_id)
        db.add(row)
    row.heavy_rain_mm = min(max(float(heavy_rain_mm or 30), 1), 500)
    row.rainy_day_mm = min(max(float(rainy_day_mm or 0), 0), 50)
    row.alert_registered = alert_registered is not None
    row.alert_forecast = alert_forecast is not None
    row.notify_dashboard = notify_dashboard is not None
    row.notify_bell = notify_bell is not None
    year = _int_or_none(average_since_year)
    row.average_since_year = year if year and 1950 <= year <= today_in_app_timezone().year else None
    db.commit()
    _flash(request, "success", "Configurações de chuva salvas.")
    target = (redirect_to or "").strip()
    if not target.startswith("/") or target.startswith("//"):
        target = "/dashboard"
    return _redirect(target)


