@router.get("/producao")
def production_page(
    request: Request,
    edit_id: int | None = None,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
    csrf_token: str = Depends(get_csrf_token),
):
    from app.services.coffee_sales import group_sales
    from app.services.harvest_lots import stage_of

    lote = _optional_query_int(request.query_params.get("lote"))
    if not lote and request.query_params.get("assistant_kind") == "colheita":
        lote = _optional_query_int(request.query_params.get("assistant_view"))
    if lote:
        return _redirect(f"/producao/lotes/{lote}")
    if edit_id:
        return _redirect(f"/producao/colheitas/{edit_id}/editar")
    repo = _repository(db)
    scope = _global_scope_context(request, repo)
    lots, sales = _production_lots(request, repo, db, scope) if scope.get("active_farm_id") else ([], [])
    groups = group_sales(_sort_collection_desc(sales, lambda item: item.sale_date, lambda item: item.id))
    today = today_in_app_timezone()
    for lot in lots:
        lot["stage_code"], lot["stage_label"] = stage_of(lot["harvest"], lot["available"])
        lot["estimated"] = bool(lot["harvest"].sacks_estimated)
    filters = {
        "todos": lambda lot: True,
        "saldo": lambda lot: lot["available"] > 0,
        "semclass": lambda lot: lot["classification"] is None,
        "vendidos": lambda lot: lot["available"] <= 0,
    }
    selected = request.query_params.get("filtro") if request.query_params.get("filtro") in filters else "todos"
    search = _normalize_search_value((request.query_params.get("busca") or "").strip())
    shown = [lot for lot in lots if filters[selected](lot)]
    if search:
        shown = [lot for lot in shown if search in _normalize_search_value(f"{lot['code']} {lot['plot']} {lot['variety']}")]
    produced = sum(lot["produced"] for lot in lots)
    harvested_plots = {lot["harvest"].plot_id: lot["harvest"].plot for lot in lots if lot["harvest"].plot}
    area = sum(float(plot.area_hectares or 0) for plot in harvested_plots.values())
    classified = [lot for lot in lots if lot["classification"] is not None]
    unclassified = [lot for lot in lots if lot["classification"] is None and lot["produced"] > 0]
    estimated = [lot for lot in lots if lot["estimated"]]
    gross = sum(g["gross"] for g in groups)
    sold = sum(g["sacks"] for g in groups)
    attention = []
    for g in sorted((g for g in groups if g["status"] == "negociado"), key=lambda g: g["delivery_due_date"] or date.max)[:2]:
        due = g["delivery_due_date"]
        attention.append({"tone": "error" if due and due < today else "info", "icon": "truck", "href": f"/producao/comercializacao?venda={g['code']}",
                          "title": (f"Entrega atrasada: {_format_decimal_br(g['sacks'])} sc" if due and due < today else
                                    f"Entregar {_format_decimal_br(g['sacks'])} sc" + (f" até {due.strftime('%d/%m')}" if due else "")),
                          "detail": f"Venda {g['code']} · {g['buyer_name']}"})
    for g in [g for g in groups if g["status"] in {"entregue", "faturado"}][:2]:
        attention.append({"tone": "done", "icon": "money", "href": f"/producao/comercializacao?venda={g['code']}",
                          "title": f"Receber R$ {_format_decimal_br(g['net'])}", "detail": f"Venda {g['code']} · {g['buyer_name']}"})
    if unclassified:
        codes = ", ".join(lot["code"] for lot in unclassified[:3]) + ("…" if len(unclassified) > 3 else "")
        attention.append({"tone": "warn", "icon": "check", "href": "/producao/classificacao",
                          "title": f"Classificar {len(unclassified)} lote{'s' if len(unclassified) > 1 else ''}",
                          "detail": f"{codes} · saber a qualidade ajuda a negociar melhor"})
    for lot in [lot for lot in estimated if (today - lot["harvest"].harvest_date).days > 30][:1]:
        attention.append({"tone": "info", "icon": "scale", "href": f"/producao/lotes/{lot['id']}",
                          "title": f"Informar o benefício do {lot['code']}",
                          "detail": "O volume ainda é estimado. Registre as sacas reais."})
    return templates.TemplateResponse(
        "production.html",
        _base_context(
            request, user, csrf_token, "harvest", _repo=repo,
            pd_lots=shown, pd_lot_total=len(lots), pd_filter=selected, pd_search=request.query_params.get("busca") or "",
            pd_filter_counts={key: sum(1 for lot in lots if test(lot)) for key, test in filters.items()},
            pd_attention=attention[:4], pd_today=today,
            pd_kpi={
                "produced": produced, "lots": len(lots), "area": area, "per_ha": produced / area if area else None,
                "last_harvest": max((lot["harvest"].harvest_date for lot in lots), default=None),
                "estimated_codes": [lot["code"] for lot in estimated],
                "classified": len(classified), "classified_sacks": sum(lot["produced"] for lot in classified),
                "unclassified_codes": [lot["code"] for lot in unclassified],
                "unclassified_sacks": sum(lot["produced"] for lot in unclassified),
                "gross": gross, "sold": sold, "sales": len(groups), "avg_price": gross / sold if sold else None,
                "received": sum(g["net"] for g in groups if g["status"] == "recebido"),
                "to_receive": sum(g["net"] for g in groups if g["status"] != "recebido"),
                "delivered": sum(lot["delivered"] for lot in lots), "negotiated": sum(lot["negotiated"] for lot in lots),
                "available": sum(lot["available"] for lot in lots),
            },
        ),
    )


def _lot_in_scope(request: Request, repo: FarmRepository, lot_id: int, scope: dict) -> HarvestRecord | None:
    harvest = repo.get_harvest(lot_id)
    if not harvest or not _plot_matches_scope(harvest.plot, scope):
        return None
    return harvest


@router.get("/producao/lotes/{lot_id}")
def lot_detail_page(
    lot_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
    csrf_token: str = Depends(get_csrf_token),
):
    from app.services.coffee_sales import group_sales
    from app.services.harvest_lots import LOT_STAGES, STAGE_HINTS, stage_of, timeline

    repo = _repository(db)
    scope = _global_scope_context(request, repo)
    harvest = _lot_in_scope(request, repo, lot_id, scope)
    if not harvest:
        _flash(request, "error", "Lote não encontrado na fazenda ativa.")
        return _redirect("/producao")
    analyses = (db.query(CoffeeClassification).options(defer(CoffeeClassification.report_data),
                                                       selectinload(CoffeeClassification.attachments).load_only(CoffeeClassificationAttachment.filename))
                .filter(CoffeeClassification.harvest_id == harvest.id)
                .order_by(CoffeeClassification.analysis_date.desc(), CoffeeClassification.id.desc()).all())
    own_sales = (db.query(CoffeeCommercializationRecord).filter(CoffeeCommercializationRecord.harvest_id == harvest.id).all())
    codes = {s.sale_code for s in own_sales if s.sale_code}
    group_records = (db.query(CoffeeCommercializationRecord).filter(CoffeeCommercializationRecord.sale_code.in_(codes),
                                                                    CoffeeCommercializationRecord.farm_id == harvest.plot.farm_id)
                     .order_by(CoffeeCommercializationRecord.sale_date.desc(), CoffeeCommercializationRecord.id.desc()).all()) if codes else []
    group_records += [s for s in own_sales if not s.sale_code]
    groups = group_sales(group_records)
    produced = float(harvest.sacks_produced or 0)
    sold = sum(float(s.equivalent_sacks or 0) for s in own_sales)
    negotiated = sum(float(s.equivalent_sacks or 0) for s in own_sales if (s.status or "negociado") == "negociado")
    available = max(produced - sold, 0)
    priced = [s for s in own_sales if float(s.equivalent_sacks or 0) > 0]
    ref_price = (sum(float(s.unit_price or 0) for s in priced) / len(priced)) if priced else None
    stage_code, stage_label = stage_of(harvest, available)
    today = today_in_app_timezone()
    can_sell = bool(scope.get("active_season") and available > 0 and _plot_allowed_for_season_launch(harvest.plot, scope)
                    and harvest_matches_season(harvest, scope.get("active_season")))
    lot_groups = []
    for g in groups:
        mine = sum(lot["sacks"] for lot in g["lots"] if lot["harvest_id"] == harvest.id)
        lot_groups.append({**g, "mine": mine})
    return templates.TemplateResponse(
        "lot_detail.html",
        _base_context(
            request, user, csrf_token, "harvest", _repo=repo,
            lot=harvest, lot_code=_lot_display_code(harvest), lot_analyses=analyses, lot_latest=analyses[0] if analyses else None,
            lot_sales=lot_groups, lot_timeline=timeline(harvest, analyses, groups, today),
            lot_produced=produced, lot_sold=sold, lot_negotiated=negotiated, lot_delivered=sold - negotiated,
            lot_available=available, lot_value_estimate=available * ref_price if ref_price else None,
            lot_stage_code=stage_code, lot_stage_label=stage_label, lot_stages=LOT_STAGES, lot_stage_hints=STAGE_HINTS,
            lot_can_sell=can_sell, lot_has_sales=bool(own_sales), lot_today=today,
            lot_quality=_classification_label(analyses[0] if analyses else None),
            lot_legacy=harvest.season_id is None and bool(scope.get("active_season_id")),
            lot_per_ha=produced / float(harvest.plot.area_hectares) if harvest.plot and harvest.plot.area_hectares else None,
        ),
    )


@router.get("/producao/colheitas/nova")
@router.get("/producao/colheitas/{lot_id}/editar")
def harvest_form_page(
    request: Request,
    lot_id: int | None = None,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
    csrf_token: str = Depends(get_csrf_token),
):
    from app.services.harvest_lots import (COFFEE_STAGES, DESTINATIONS, HARVEST_TYPES, MEASURE_HINTS, MEASURE_UNITS,
                                           farm_yield_average)

    repo = _repository(db)
    scope, denied = _launch_scope_or_redirect(request, repo, "/producao")
    if denied:
        return denied
    farm_ids, variety_ids = _scoped_plot_filters(request, scope["active_season"])
    plots = repo.list_plots(farm_ids=farm_ids, variety_ids=variety_ids)
    launch_plots = _season_launch_plots(plots, scope)
    harvest = None
    if lot_id:
        harvest = _lot_in_scope(request, repo, lot_id, scope)
        if not harvest:
            _flash(request, "error", "Lote não encontrado na fazenda ativa.")
            return _redirect("/producao")
        if harvest.plot and harvest.plot not in launch_plots:
            launch_plots = [*launch_plots, harvest.plot]
    last_by_plot = {}
    for item in repo.list_harvests():
        if item.plot_id in {p.id for p in launch_plots} and harvest_matches_season(item, scope.get("active_season")):
            if item.plot_id not in last_by_plot or item.harvest_date > last_by_plot[item.plot_id]:
                last_by_plot[item.plot_id] = item.harvest_date
    plot_ids = [p.id for p in launch_plots]
    yields = {unit: farm_yield_average(db, plot_ids, unit) or MEASURE_UNITS[unit][2] for unit in ("litros", "sacos_roca")}
    yields_learned = {unit: farm_yield_average(db, plot_ids, unit) is not None for unit in ("litros", "sacos_roca")}
    season = scope.get("active_season")
    locked = bool(harvest and repo.harvest_has_commercializations(harvest.id))
    return templates.TemplateResponse(
        "harvest_form.html",
        _base_context(
            request, user, csrf_token, "harvest", _repo=repo,
            hv=harvest, hv_locked=locked, hv_plots=sorted(launch_plots, key=lambda p: p.name or ""),
            hv_last_by_plot=last_by_plot, hv_units=MEASURE_UNITS, hv_unit_hints=MEASURE_HINTS, hv_yields=yields,
            hv_yields_learned=yields_learned, hv_types=HARVEST_TYPES, hv_destinations=DESTINATIONS,
            hv_coffee_stages=COFFEE_STAGES, hv_season=season,
            hv_next_code=harvest.lot_code if harvest else _suggest_next_harvest_lot_code(repo),
            hv_today=today_in_app_timezone(),
            hv_totals={"produced": sum(float(h.sacks_produced or 0) for h in repo.list_harvests()
                                       if h.plot_id in plot_ids and harvest_matches_season(h, season))},
            hv_preselect_plot=_optional_query_int(request.query_params.get("talhao")),
        ),
    )


@router.post("/producao/lotes/{lot_id}/etapa")
def lot_stage_action(
    lot_id: int,
    request: Request,
    csrf_token: str = Form(...),
    stage: str = Form(...),
    event_date: str | None = Form(None),
    storage_location: str | None = Form(None),
    warehouse_receipt: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    from app.services.harvest_lots import LOT_STAGE_LABELS, add_event

    del user
    validate_csrf(request, csrf_token)
    repo = _repository(db)
    scope = _global_scope_context(request, repo)
    harvest = _lot_in_scope(request, repo, lot_id, scope)
    if not harvest:
        _flash(request, "error", "Lote não encontrado na fazenda ativa.")
        return _redirect("/producao")
    stage = (stage or "").strip()
    if stage not in LOT_STAGE_LABELS:
        _flash(request, "error", "Escolha uma etapa válida.")
        return _redirect(f"/producao/lotes/{lot_id}")
    if stage == "beneficiado" and harvest.sacks_estimated:
        _flash(request, "error", "Para marcar como beneficiado, informe as sacas reais em “Informar benefício”.")
        return _redirect(f"/producao/lotes/{lot_id}")
    when = _date_or_none(event_date) or today_in_app_timezone()
    location = _clean_text(storage_location) if stage == "armazem" else None
    receipt = _clean_text(warehouse_receipt) if stage == "armazem" else None
    if stage == "armazem" and not location:
        _flash(request, "error", "Informe o nome do armazém.")
        return _redirect(f"/producao/lotes/{lot_id}")
    if stage == harvest.lot_stage and location == harvest.storage_location and receipt == harvest.warehouse_receipt:
        return _redirect(f"/producao/lotes/{lot_id}")
    titles = {"secagem": "Em secagem", "tulha": "Entrou na tulha", "beneficiado": "Pronto para vender",
              "armazem": f"Levado para {location}"}
    detail = f"Recibo de depósito nº {receipt}" if receipt else None
    harvest.lot_stage = stage
    harvest.storage_location = location
    harvest.warehouse_receipt = receipt
    add_event(db, harvest, event_date=when, kind="etapa", stage=stage, title=titles[stage], detail=detail)
    db.commit()
    _flash(request, "success", f"Etapa do lote atualizada: {LOT_STAGE_LABELS[stage].lower()}.")
    return _redirect(f"/producao/lotes/{lot_id}")


@router.post("/producao/lotes/{lot_id}/beneficio")
def lot_processing_action(
    lot_id: int,
    request: Request,
    csrf_token: str = Form(...),
    real_sacks: str = Form(...),
    processed_on: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    from app.services.coffee_sales import parse_decimal
    from app.services.harvest_lots import MEASURE_UNITS, _fmt, add_event

    del user
    validate_csrf(request, csrf_token)
    repo = _repository(db)
    scope = _global_scope_context(request, repo)
    harvest = _lot_in_scope(request, repo, lot_id, scope)
    if not harvest:
        _flash(request, "error", "Lote não encontrado na fazenda ativa.")
        return _redirect("/producao")
    sacks = parse_decimal(real_sacks)
    if not sacks or sacks <= 0:
        _flash(request, "error", "Informe quantas sacas de 60 kg o lote rendeu.")
        return _redirect(f"/producao/lotes/{lot_id}")
    sold = sum(float(s.equivalent_sacks or 0) for s in
               db.query(CoffeeCommercializationRecord).filter(CoffeeCommercializationRecord.harvest_id == harvest.id).all())
    if sacks + 0.0001 < sold:
        _flash(request, "error", f"O lote já tem {_format_decimal_br(sold)} sc vendidas. Confira as sacas reais ou ajuste as vendas.")
        return _redirect(f"/producao/lotes/{lot_id}")
    when = _date_or_none(processed_on) or today_in_app_timezone()
    before = float(harvest.sacks_produced or 0)
    detail = f"{_fmt(sacks, 2)} sacas de 60 kg"
    if harvest.sacks_estimated:
        detail += f" (estimado era ≈ {_fmt(before, 0)})"
    if harvest.measured_quantity and harvest.measure_unit in {"litros", "sacos_roca"}:
        real_yield = float(harvest.measured_quantity) / sacks
        harvest.yield_factor = round(real_yield, 3)
        detail += f" · rendimento {_fmt(real_yield, 0)} {MEASURE_UNITS[harvest.measure_unit][3]}"
    harvest.sacks_produced = round(sacks, 2)
    harvest.sacks_estimated = False
    harvest.processed_on = when
    if harvest.lot_stage in (None, "secagem", "tulha"):
        harvest.lot_stage = "beneficiado"
    area = float(harvest.plot.area_hectares or 0) if harvest.plot else 0
    harvest.productivity_per_hectare = round(sacks / area, 2) if area else 0
    add_event(db, harvest, event_date=when, kind="beneficio", stage="beneficiado", title="Beneficiado", detail=detail)
    db.commit()
    _flash(request, "success", f"Benefício registrado: {_format_decimal_br(sacks)} sc reais no lote.")
    return _redirect(f"/producao/lotes/{lot_id}")

def _harvest_measure(measure_unit, measured_quantity, yield_factor, sacks_produced, destination, current=None):
    """Converte a medida da roça em sacas de 60 kg. Devolve (sacas, campos extras do lote)."""
    from app.services.coffee_sales import parse_decimal
    from app.services.harvest_lots import MEASURE_UNITS, estimate_sacks, initial_stage

    unit = (measure_unit or "").strip() if isinstance(measure_unit, str) else ""
    if unit not in MEASURE_UNITS:
        if sacks_produced is None or isinstance(sacks_produced, FieldInfo):
            raise ValueError("Informe quanto foi colhido.")
        sacks = float(sacks_produced)
        if sacks <= 0:
            raise ValueError("Informe quanto foi colhido.")
        return sacks, {}
    quantity = parse_decimal(measured_quantity) if isinstance(measured_quantity, str) else None
    if not quantity or quantity <= 0:
        raise ValueError("Informe quanto foi colhido.")
    factor = parse_decimal(yield_factor) if isinstance(yield_factor, str) else None
    if unit != "sc_60" and (not factor or factor <= 0):
        factor = MEASURE_UNITS[unit][2]
    sacks = estimate_sacks(unit, quantity, factor)
    if sacks <= 0:
        raise ValueError("A quantidade colhida resultou em zero sacas. Confira o rendimento.")
    extra = {"measure_unit": unit, "measured_quantity": quantity, "yield_factor": factor if unit != "sc_60" else None}
    if current is not None and not current.sacks_estimated and current.measure_unit and current.measure_unit != "sc_60":
        # lote já beneficiado: a medida da roça muda, mas as sacas reais continuam
        return float(current.sacks_produced or 0), extra
    extra["sacks_estimated"] = unit != "sc_60"
    if current is None:
        extra["lot_stage"] = initial_stage(unit, destination if isinstance(destination, str) else None)
    elif unit == "sc_60":
        extra["lot_stage"] = current.lot_stage or "beneficiado"
    return sacks, extra


def _validate_harvest_percentage(value: str | None, label: str) -> float | None:
    parsed = _float_or_none(value)
    if parsed is None:
        return None
    if parsed < 0 or parsed > 100:
        raise ValueError(f"{label} deve estar entre 0 e 100.")
    return parsed


def _validate_harvest_date_for_season(raw_date: str, season: CropSeason | None) -> date:
    try:
        harvest_day = date.fromisoformat(raw_date)
    except (TypeError, ValueError):
        raise ValueError("Informe uma data válida para a colheita.")
    if season and not _within_scope(harvest_day, season.start_date, season.end_date):
        raise ValueError(
            f"A data da colheita deve estar dentro do período da safra ativa: "
            f"{season.start_date.strftime('%d/%m/%Y')} a {season.end_date.strftime('%d/%m/%Y')}."
        )
    return harvest_day


def _suggest_next_harvest_lot_code(repo: FarmRepository, reference_date: date | None = None) -> str:
    base_date = reference_date or today_in_app_timezone()
    year_start = date(base_date.year, 1, 1)
    year_end = date(base_date.year, 12, 31)
    seq = (
        repo.db.query(HarvestRecord)
        .filter(HarvestRecord.harvest_date >= year_start, HarvestRecord.harvest_date <= year_end)
        .count()
    ) + 1
    return f"{base_date.year}-L{seq:03d}"


def _commercialization_record_matches_scope(record: CoffeeCommercializationRecord, scope: dict) -> bool:
    if scope.get("active_farm_id") and record.farm_id != scope["active_farm_id"]:
        return False
    if record.harvest and not _plot_matches_scope(record.harvest.plot, scope):
        return False
    return True


@router.post("/producao")
def create_harvest_action(
    request: Request,
    csrf_token: str = Form(...),
    plot_id: int = Form(...),
    harvest_date: str = Form(...),
    lot_code: str | None = Form(None),
    sacks_produced: float | None = Form(None),
    harvest_type: str | None = Form(None),
    coffee_stage: str | None = Form(None),
    initial_destination: str | None = Form(None),
    responsible_name: str | None = Form(None),
    work_shift: str | None = Form(None),
    maturation_percentage: str | None = Form(None),
    impurity_percentage: str | None = Form(None),
    input_moisture_percentage: str | None = Form(None),
    volume_count: str | None = Form(None),
    notes: str | None = Form(None),
    measure_unit: str | None = Form(None),
    measured_quantity: str | None = Form(None),
    yield_factor: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    del user
    validate_csrf(request, csrf_token)
    repo = _repository(db)
    plot, scope, denied = _resolve_plot_in_scope(request, repo, plot_id, "/producao")
    if denied:
        return denied
    if not _plot_allowed_for_season_launch(plot, scope):
        _flash(request, "error", "O setor selecionado não está vinculado à safra ativa.")
        return _redirect("/producao")
    try:
        _validate_harvest_date_for_season(harvest_date, scope.get("active_season"))
        maturation_value = _validate_harvest_percentage(maturation_percentage, "Percentual de maturação")
        impurity_value = _validate_harvest_percentage(impurity_percentage, "Percentual de impureza")
        moisture_value = _validate_harvest_percentage(input_moisture_percentage, "Umidade na entrada")
    except ValueError as exc:
        _flash(request, "error", str(exc))
        return _redirect("/producao/colheitas/nova")
    try:
        sacks_value, measure_extra = _harvest_measure(measure_unit, measured_quantity, yield_factor, sacks_produced,
                                                      initial_destination, harvest if False else None)
    except ValueError as exc:
        _flash(request, "error", str(exc))
        return _redirect("/producao/colheitas/nova")
    area = float(plot.area_hectares) if plot else 0
    harvest = create_harvest(
        repo,
        {
            "plot_id": plot.id,
            "season_id": scope["active_season_id"],
            "harvest_date": harvest_date,
            "lot_code": lot_code,
            "sacks_produced": sacks_value,
                **measure_extra,
            "harvest_type": (harvest_type or "").strip() or None,
            "coffee_stage": (coffee_stage or "").strip() or None,
            "initial_destination": (initial_destination or "").strip() or None,
            "responsible_name": (responsible_name or "").strip() or None,
            "work_shift": (work_shift or "").strip() or None,
            "maturation_percentage": maturation_value,
            "impurity_percentage": impurity_value,
            "input_moisture_percentage": moisture_value,
            "volume_count": _int_or_none(volume_count),
            "notes": notes,
        },
        area,
    )
    _flash(request, "success", f"Colheita registrada. Lote {harvest.lot_code} criado.")
    return _redirect(f"/producao/lotes/{harvest.id}")


@router.post("/producao/{record_id}/vincular-safra")
def link_legacy_harvest_to_season_action(
    record_id: int,
    request: Request,
    csrf_token: str = Form(...),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    validate_csrf(request, csrf_token)
    repo = _repository(db)
    scope, denied = _launch_scope_or_redirect(request, repo, "/producao")
    if denied:
        return denied
    harvest = repo.get_harvest(record_id)
    season = scope["active_season"]
    if not harvest or not harvest.plot or harvest.plot.farm_id != scope["active_farm_id"]:
        _flash(request, "error", "Colheita não encontrada na fazenda ativa.")
        return _redirect("/producao")
    if harvest.season_id is not None:
        _flash(request, "error", "Esta colheita já possui uma safra vinculada.")
        return _redirect("/producao")
    if not season.plots or not any(plot.id == harvest.plot_id for plot in season.plots):
        _flash(request, "error", "O setor da colheita precisa estar vinculado à safra ativa.")
        return _redirect("/producao")
    if not _within_scope(harvest.harvest_date, season.start_date, season.end_date):
        _flash(request, "error", "A data da colheita está fora do período da safra ativa.")
        return _redirect("/producao")
    repo.update(harvest, {"season_id": season.id})
    _flash(request, "success", "Colheita vinculada à safra ativa com sucesso.")
    return _redirect("/producao")


@router.post("/producao/{record_id}/editar")
def update_harvest_action(
    record_id: int,
    request: Request,
    csrf_token: str = Form(...),
    plot_id: int = Form(...),
    harvest_date: str = Form(...),
    lot_code: str | None = Form(None),
    sacks_produced: float | None = Form(None),
    harvest_type: str | None = Form(None),
    coffee_stage: str | None = Form(None),
    initial_destination: str | None = Form(None),
    responsible_name: str | None = Form(None),
    work_shift: str | None = Form(None),
    maturation_percentage: str | None = Form(None),
    impurity_percentage: str | None = Form(None),
    input_moisture_percentage: str | None = Form(None),
    volume_count: str | None = Form(None),
    notes: str | None = Form(None),
    measure_unit: str | None = Form(None),
    measured_quantity: str | None = Form(None),
    yield_factor: str | None = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    del user
    validate_csrf(request, csrf_token)
    repo = _repository(db)
    plot, scope, denied = _resolve_plot_in_scope(request, repo, plot_id, "/producao")
    if denied:
        return denied
    harvest = repo.get_harvest(record_id)
    if not harvest:
        _flash(request, "error", "Registro de producao nao encontrado.")
        return _redirect_for_request(request, "/producao")
    if not _plot_matches_scope(harvest.plot, scope):
        _flash(request, "error", "Este registro de producao nao pertence ao contexto ativo.")
        return _redirect_for_request(request, "/producao")
    if harvest.season_id is not None and harvest.season_id != scope.get("active_season_id"):
        _flash(request, "error", "Esta colheita pertence a outra safra.")
        return _redirect_for_request(request, "/producao")
    if plot.id != harvest.plot_id and not _plot_allowed_for_season_launch(plot, scope):
        _flash(request, "error", "O setor selecionado não está vinculado à safra ativa.")
        return _redirect_for_request(request, f"/producao/colheitas/{record_id}/editar")
    earliest_analysis = (db.query(func.min(CoffeeClassification.analysis_date))
                         .filter(CoffeeClassification.harvest_id == harvest.id).scalar())
    if earliest_analysis:
        if plot.id != harvest.plot_id or (lot_code or "").strip() != (harvest.lot_code or "").strip():
            _flash(request, "error", "Não é possível alterar o lote ou o setor enquanto houver análises de classificação vinculadas.")
            return _redirect_for_request(request, f"/producao/colheitas/{record_id}/editar")
        try:
            if date.fromisoformat(harvest_date) > earliest_analysis:
                _flash(request, "error", "A data da colheita não pode ser posterior às análises já registradas.")
                return _redirect_for_request(request, f"/producao/colheitas/{record_id}/editar")
        except ValueError:
            pass
    try:
        _validate_harvest_date_for_season(harvest_date, scope.get("active_season"))
        maturation_value = _validate_harvest_percentage(maturation_percentage, "Percentual de maturação")
        impurity_value = _validate_harvest_percentage(impurity_percentage, "Percentual de impureza")
        moisture_value = _validate_harvest_percentage(input_moisture_percentage, "Umidade na entrada")
    except ValueError as exc:
        _flash(request, "error", str(exc))
        return _redirect_for_request(request, f"/producao/colheitas/{record_id}/editar")
    try:
        sacks_value, measure_extra = _harvest_measure(measure_unit, measured_quantity, yield_factor, sacks_produced,
                                                      initial_destination, harvest if True else None)
    except ValueError as exc:
        _flash(request, "error", str(exc))
        return _redirect(f"/producao/colheitas/{record_id}/editar")
    area = float(plot.area_hectares) if plot else 0
    try:
        update_harvest(
            repo,
            harvest,
            {
                "plot_id": plot.id,
                "harvest_date": harvest_date,
                "lot_code": lot_code,
                "sacks_produced": sacks_value,
                **measure_extra,
                "harvest_type": (harvest_type or "").strip() or None,
                "coffee_stage": (coffee_stage or "").strip() or None,
                "initial_destination": (initial_destination or "").strip() or None,
                "responsible_name": (responsible_name or "").strip() or None,
                "work_shift": (work_shift or "").strip() or None,
                "maturation_percentage": maturation_value,
                "impurity_percentage": impurity_value,
                "input_moisture_percentage": moisture_value,
                "volume_count": _int_or_none(volume_count),
                "notes": notes,
            },
            area,
        )
    except ValueError as exc:
        _flash(request, "error", str(exc))
        return _redirect_for_request(request, f"/producao/colheitas/{record_id}/editar")
    _flash(request, "success", "Colheita atualizada com sucesso.")
    return _redirect_for_request(request, f"/producao/lotes/{record_id}")


@router.post("/producao/{record_id}/excluir")
def delete_harvest_action(
    record_id: int,
    request: Request,
    csrf_token: str = Form(...),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_web),
):
    del user
    validate_csrf(request, csrf_token)
    repo = _repository(db)
    scope = _global_scope_context(request, repo)
    harvest = repo.get_harvest(record_id)
    if not harvest:
        _flash(request, "error", "Registro de producao nao encontrado.")
        return _redirect("/producao")
    if not _plot_matches_scope(harvest.plot, scope):
        _flash(request, "error", "Este registro de producao nao pertence ao contexto ativo.")
        return _redirect("/producao")
    if repo.harvest_has_commercializations(harvest.id):
        _flash(
            request,
            "error",
            "Nao e possivel excluir: existem registros de comercializacao vinculados a este lote.",
        )
        return _redirect("/producao")
    if db.query(CoffeeClassification.id).filter_by(harvest_id=harvest.id).first():
        _flash(request, "error", "Não é possível excluir uma colheita com análises de classificação vinculadas.")
        return _redirect("/producao")
    repo.delete(harvest)
    _flash(request, "success", "Colheita excluida com sucesso.")
    return _redirect("/producao")


def _classification_harvests(repo, scope):
    farm, season = scope.get("active_farm"), scope.get("active_season")
    if not farm or not season:
        return []
    harvests = (repo.db.query(HarvestRecord).join(Plot, HarvestRecord.plot_id == Plot.id)
                .options(joinedload(HarvestRecord.plot)).filter(Plot.farm_id == farm.id)
                .order_by(HarvestRecord.harvest_date.desc(), HarvestRecord.id.desc()).all())
    return [harvest for harvest in harvests if harvest_matches_season(harvest, season)]


def _analysis_view(analysis, *, mini: bool = False) -> dict:
    """Dados prontos para exibir uma análise: radar, barras, faixa da nota e tipo de análise."""
    from app.services.coffee_classification import ANALYSIS_KINDS, radar_axes, radar_points, score_band
    profile = analysis.sensory_profile
    pairs = profile.attribute_pairs if profile else []
    scale = profile.scale_max if profile else 10
    labels = [label for label, _ in pairs]
    values = [float(value or 0) for _, value in pairs]
    geo = {"cx": 22.0, "cy": 22.0, "radius": 19.0} if mini else {}
    band, tone = score_band(analysis.sensory_score)
    kinds = {key: label for key, label, _ in ANALYSIS_KINDS}
    kind = analysis.analysis_kind or ("ambos" if profile or analysis.sensory_score is not None else "fisica")
    return {
        "obj": analysis, "id": analysis.id, "scale": scale, "has_profile": len(values) >= 3,
        "pairs": [{"label": label, "value": value, "pct": round(min(value / scale, 1) * 100, 1) if scale else 0}
                  for label, value in zip(labels, values)],
        "radar": radar_points(values, scale, **geo), "ring": radar_points([scale] * len(values), scale, **geo),
        "ring_half": radar_points([scale / 2] * len(values), scale, **geo), "axes": radar_axes(labels) if not mini else [],
        "band": band, "tone": tone, "kind": kind, "kind_label": analysis.method or kinds.get(kind, ""),
        "score": float(analysis.sensory_score) if analysis.sensory_score is not None else None,
        "files": ([{"name": analysis.report_filename, "url": f"/producao/classificacao/{analysis.id}/laudo"}]
                  if analysis.report_filename else [])
                 + [{"name": item.filename, "url": f"/producao/classificacao/{analysis.id}/laudo?attachment_id={item.id}"}
                    for item in analysis.attachments],
    }


def _classification_data(db: Session, harvests: list[HarvestRecord]):
    """Análises da safra (mais recentes primeiro) agrupadas por lote."""
    ids = [item.id for item in harvests]
    analyses = (db.query(CoffeeClassification)
                .options(defer(CoffeeClassification.report_data), selectinload(CoffeeClassification.attachments)
                         .load_only(CoffeeClassificationAttachment.filename), selectinload(CoffeeClassification.sensory_profile))
                .filter(CoffeeClassification.harvest_id.in_(ids))
                .order_by(CoffeeClassification.analysis_date.desc(), CoffeeClassification.id.desc()).all()) if ids else []
    by_lot: dict[int, list] = {}
    for analysis in analyses:
        by_lot.setdefault(analysis.harvest_id, []).append(analysis)
    return analyses, by_lot


def _quality_price_refs(db: Session, harvests, by_lot) -> list[dict]:
    """Preço médio das vendas da safra por faixa de qualidade do lote vendido."""
    ids = [item.id for item in harvests]
    if not ids:
        return []
    sales = db.query(CoffeeCommercializationRecord).filter(CoffeeCommercializationRecord.harvest_id.in_(ids)).all()
    buckets = {"top": [], "ok": [], "std": []}
    for sale in sales:
        latest = (by_lot.get(sale.harvest_id) or [None])[0]
        if latest is None or latest.sensory_score is None:
            continue
        score = float(latest.sensory_score)
        buckets["top" if score >= 84 else "ok" if score >= 80 else "std"].append(float(sale.unit_price or 0))
    labels = {"top": "Especial 84+ pts", "ok": "Especial 80–84 pts", "std": "Comercial (abaixo de 80)"}
    return [{"label": labels[key], "min": min(values), "max": max(values)} for key, values in buckets.items() if values]


@router.get("/producao/classificacao")
def coffee_classification_page(request: Request, db: Session = Depends(get_db), user: User = Depends(get_current_user_web),
                               csrf_token: str = Depends(get_csrf_token)):
    from collections import Counter

    from app.services.coffee_classification import attribute_rows, attribute_usage, default_scale
    from app.services.harvest_lots import stage_of

    params = request.query_params
    harvest_param = _optional_query_int(params.get("harvest_id"))
    origem = "producao" if params.get("origem") == "producao" else None
    if params.get("novo"):
        return _redirect_with_query("/producao/classificacao/nova", lote=harvest_param, origem=origem)
    if _optional_query_int(params.get("edit_id")):
        return _redirect(f"/producao/classificacao/{_optional_query_int(params.get('edit_id'))}/editar")
    if _optional_query_int(params.get("analise")):
        return _redirect(f"/producao/classificacao/{_optional_query_int(params.get('analise'))}")
    repo = _repository(db)
    scope = _global_scope_context(request, repo, user)
    harvests = _classification_harvests(repo, scope)
    analyses, by_lot = _classification_data(db, harvests)
    today = today_in_app_timezone()
    rows = []
    for harvest in harvests:
        mine = by_lot.get(harvest.id, [])
        latest = _analysis_view(mine[0], mini=True) if mine else None
        stage = stage_of(harvest)[1]
        rows.append({"harvest": harvest, "code": _lot_display_code(harvest), "latest": latest, "count": len(mine),
                     "sacks": float(harvest.sacks_produced or 0), "estimated": bool(harvest.sacks_estimated),
                     "plot": harvest.plot.name if harvest.plot else "Setor removido",
                     "variety": harvest.plot.variety.name if harvest.plot and harvest.plot.variety else "",
                     "stage": stage, "age": (today - harvest.harvest_date).days if harvest.harvest_date else None})
    classified = [row for row in rows if row["latest"]]
    scored = [row for row in classified if row["latest"]["score"] is not None]
    weight = sum(row["sacks"] for row in scored)
    avg = (sum(row["latest"]["score"] * row["sacks"] for row in scored) / weight) if weight else (
        sum(row["latest"]["score"] for row in scored) / len(scored) if scored else None)
    best = max(scored, key=lambda row: row["latest"]["score"], default=None)
    drinks = Counter(row["latest"]["obj"].beverage for row in classified if row["latest"]["obj"].beverage)
    top_drink = drinks.most_common(1)[0][0] if drinks else None
    tests = {"todos": lambda r: True, "especiais": lambda r: bool(r["latest"]) and (r["latest"]["score"] or 0) >= 80,
             "comerciais": lambda r: bool(r["latest"]) and r["latest"]["score"] is not None and r["latest"]["score"] < 80,
             "sem": lambda r: not r["latest"]}
    selected = params.get("filtro") if params.get("filtro") in tests else "todos"
    search = _normalize_search_value((params.get("busca") or "").strip())
    shown = [row for row in rows if tests[selected](row)]
    if search:
        shown = [row for row in shown if search in _normalize_search_value(
            f"{row['code']} {row['plot']} {row['variety']} {(row['latest']['obj'].evaluator or '') if row['latest'] else ''}")]
    shown.sort(key=lambda row: (row["latest"] is None, -(row["latest"]["score"] or 0) if row["latest"] else 0))
    attributes = attribute_rows(db, user.organization_id)
    usage = attribute_usage(db, user.organization_id)
    can_delete = user_has_permission(db, user, "data.delete")
    return templates.TemplateResponse("coffee_classification.html", _base_context(
        request, user, csrf_token, "coffee_classification", _repo=repo, title="Classificação do café",
        cl_rows=shown, cl_total=len(rows), cl_filter=selected, cl_search=params.get("busca") or "",
        cl_counts={key: sum(1 for row in rows if test(row)) for key, test in tests.items()},
        cl_pending=[row for row in rows if not row["latest"]], cl_focus=harvest_param,
        cl_kpi={"classified": len(classified), "total": len(rows), "classified_sacks": sum(r["sacks"] for r in classified),
                "total_sacks": sum(r["sacks"] for r in rows), "avg": avg, "weighted": bool(weight), "best": best,
                "drink": top_drink, "drink_lots": drinks.get(top_drink, 0) if top_drink else 0,
                "drink_sacks": sum(r["sacks"] for r in classified if r["latest"]["obj"].beverage == top_drink) if top_drink else 0,
                "analyses": len(analyses)},
        cl_attributes=[{**row, "uses": usage.get(row["key"], 0)} for row in attributes],
        cl_scale=default_scale(db, user.organization_id), cl_can_delete=can_delete,
        cl_open_attributes=bool(params.get("atributos")),
    ))


def _classification_form_render(request: Request, db: Session, user: User, csrf_token: str, *, analysis=None,
                                prefill: dict | None = None, error: str | None = None, status_code: int = 200):
    from app.services.coffee_classification import (ANALYSIS_KINDS, COFFEE_BEVERAGES, COFFEE_TYPES, FLAVORS, SIEVES,
                                                     default_scale, sensory_attributes_for_org, sensory_definitions_for_edit)
    repo = _repository(db)
    scope = _global_scope_context(request, repo, user)
    harvests = _classification_harvests(repo, scope)
    _, by_lot = _classification_data(db, harvests)
    definitions = sensory_attributes_for_org(db, user.organization_id)
    profile = analysis.sensory_profile if analysis else None
    attrs = sensory_definitions_for_edit(definitions, profile)
    p = dict(prefill or {})
    if analysis and not prefill:
        p = {"harvest_id": analysis.harvest_id, "analysis_date": analysis.analysis_date.isoformat(),
             "evaluator": analysis.evaluator or "", "sample_number": analysis.sample_number or "",
             "analysis_kind": analysis.analysis_kind or ("ambos" if profile or analysis.sensory_score is not None else "fisica"),
             "beverage": analysis.beverage or "", "coffee_type": analysis.coffee_type or "", "sieve": analysis.sieve or "",
             "moisture": _format_decimal_br(analysis.moisture) if analysis.moisture is not None else "",
             "defects": analysis.defects or "",
             "broca_percentage": _format_decimal_br(analysis.broca_percentage) if analysis.broca_percentage is not None else "",
             "sensory_score": _format_decimal_br(analysis.sensory_score) if analysis.sensory_score is not None else "",
             "sensory_notes": analysis.sensory_notes or "", "notes": analysis.notes or "", "flavors": analysis.flavors,
             "sensory": profile.attributes if profile else {}, "sensory_scale": profile.scale_max if profile else None}
    if not analysis and "harvest_id" not in p:
        p["harvest_id"] = _optional_query_int(getattr(request, "query_params", {}).get("lote"))
    p.setdefault("analysis_kind", "ambos")
    p.setdefault("flavors", [])
    p.setdefault("sensory", {})
    scale = int(p.get("sensory_scale") or default_scale(db, user.organization_id))
    lots = []
    for harvest in harvests:
        count = len(by_lot.get(harvest.id, []))
        lots.append({"id": harvest.id, "code": _lot_display_code(harvest), "count": count,
                     "sub": f"{harvest.plot.name if harvest.plot else 'Setor removido'} · {'≈ ' if harvest.sacks_estimated else ''}"
                            f"{_format_decimal_br(harvest.sacks_produced, 0)} sc"})
    lots.sort(key=lambda lot: (lot["count"] > 0, ))
    evaluators = sorted({a.evaluator for items in by_lot.values() for a in items if a.evaluator})[:8]
    flavors = list(FLAVORS) + [item for item in p["flavors"] if item not in FLAVORS]
    sieves = list(SIEVES) + ([p["sieve"]] if p.get("sieve") and p["sieve"] not in SIEVES else [])
    type_values = [f"Tipo {value}" for value in COFFEE_TYPES]
    response = templates.TemplateResponse("classification_form.html", _base_context(
        request, user, csrf_token, "coffee_classification", _repo=repo, title="Nova análise",
        cf_analysis=analysis, cf_p=p, cf_error=error, cf_lots=lots, cf_kinds=ANALYSIS_KINDS,
        cf_beverages=COFFEE_BEVERAGES, cf_types=type_values, cf_extra_type=p.get("coffee_type") if p.get("coffee_type") and p.get("coffee_type") not in type_values else None,
        cf_sieves=sieves, cf_flavors=flavors, cf_attrs=attrs, cf_scale=scale, cf_evaluators=evaluators,
        cf_origem=getattr(request, "query_params", {}).get("origem") == "producao" or (prefill or {}).get("origem") == "producao",
        cf_price_refs=_quality_price_refs(db, harvests, by_lot), today=today_in_app_timezone(),
        cf_files=_analysis_view(analysis)["files"] if analysis else [],
    ))
    response.status_code = status_code
    return response


@router.get("/producao/classificacao/nova")
def coffee_classification_new_page(request: Request, db: Session = Depends(get_db), user: User = Depends(get_current_user_web),
                                   csrf_token: str = Depends(get_csrf_token)):
    return _classification_form_render(request, db, user, csrf_token)


@router.get("/producao/classificacao/comparar")
def coffee_classification_compare_page(request: Request, db: Session = Depends(get_db), user: User = Depends(get_current_user_web),
                                       csrf_token: str = Depends(get_csrf_token)):
    from app.services.coffee_classification import radar_axes, radar_points
    repo = _repository(db)
    scope = _global_scope_context(request, repo, user)
    harvests = _classification_harvests(repo, scope)
    _, by_lot = _classification_data(db, harvests)
    available = [h for h in harvests if by_lot.get(h.id)]
    wanted = [int(x) for x in re.findall(r"\d+", request.query_params.get("lotes") or "")]
    chosen = [h for h in available if h.id in wanted][:3] or available[:2]
    colors = ["#294127", "#1F5FA8", "#D18A00"]
    dashes = ["", "", "5 3"]
    items = []
    for index, harvest in enumerate(chosen):
        view = _analysis_view(by_lot[harvest.id][0])
        items.append({"harvest": harvest, "code": _lot_display_code(harvest), "view": view, "color": colors[index],
                      "dash": dashes[index], "values": {p["label"]: p["value"] / view["scale"] * 10 for p in view["pairs"]}})
    common = [label for label in (items[0]["values"] if items else {}) if all(label in item["values"] for item in items)]
    for item in items:
        item["radar"] = radar_points([item["values"][label] for label in common], 10)

    def row(label, getter, better=None, places=1):
        raw = [getter(item) for item in items]
        nums = [value for value in raw if isinstance(value, (int, float))]
        best = (max(nums) if better == "high" else min(nums)) if nums and better and len(items) > 1 else None
        return {"label": label, "cells": [{"text": (_format_decimal_br(value, places) if isinstance(value, (int, float)) else (value or "—")),
                                          "best": best is not None and value == best} for value in raw]}

    def num(value):
        return float(value) if value is not None else None

    def defects(item):
        digits = re.sub(r"[^\d]", "", item["view"]["obj"].defects or "")
        return int(digits) if digits else (item["view"]["obj"].defects or None)

    rows = [row("Nota final", lambda i: i["view"]["score"], "high"), row("Bebida", lambda i: i["view"]["obj"].beverage),
            row("Tipo", lambda i: i["view"]["obj"].coffee_type), row("Peneira", lambda i: i["view"]["obj"].sieve),
            row("Umidade (%)", lambda i: num(i["view"]["obj"].moisture)), row("Defeitos", defects, "low", 0)]
    for label in common:
        rows.append(row(label + " (0–10)", lambda i, label=label: round(i["values"][label], 2), "high", 2))
    return templates.TemplateResponse("classification_compare.html", _base_context(
        request, user, csrf_token, "coffee_classification", _repo=repo, title="Comparar lotes",
        cc_items=items, cc_rows=rows, cc_axes=radar_axes(common), cc_common=common,
        cc_ring=radar_points([10] * len(common), 10), cc_ring_half=radar_points([5] * len(common), 10),
        cc_available=[{"id": h.id, "code": _lot_display_code(h), "on": h in chosen,
                       "href": "/producao/classificacao/comparar?lotes=" + ",".join(
                           str(x.id) for x in ([c for c in chosen if c.id != h.id] if h in chosen else [*chosen, h][-3:]))}
                      for h in available],
        cc_colors=colors,
    ))


@router.get("/producao/classificacao/{analysis_id}")
def coffee_classification_detail_page(analysis_id: int, request: Request, db: Session = Depends(get_db),
                                      user: User = Depends(get_current_user_web), csrf_token: str = Depends(get_csrf_token)):
    repo = _repository(db)
    scope = _global_scope_context(request, repo, user)
    harvests = {h.id: h for h in _classification_harvests(repo, scope)}
    _, by_lot = _classification_data(db, list(harvests.values()))
    analysis = next((a for items in by_lot.values() for a in items if a.id == analysis_id), None)
    if not analysis:
        _flash(request, "error", "Análise não encontrada na safra ativa.")
        return _redirect("/producao/classificacao")
    harvest = harvests[analysis.harvest_id]
    versions = by_lot[harvest.id]
    index = versions.index(analysis)
    previous = versions[index + 1] if index + 1 < len(versions) else None
    sales = db.query(CoffeeCommercializationRecord).filter(CoffeeCommercializationRecord.harvest_id == harvest.id).all()
    sold = sum(float(s.equivalent_sacks or 0) for s in sales)
    available = max(float(harvest.sacks_produced or 0) - sold, 0)
    history = [a for a in reversed(versions) if a.sensory_score is not None]
    points = []
    if len(history) >= 2:
        scores = [float(a.sensory_score) for a in history]
        low, high = min(scores) - 1, max(scores) + 1
        for i, a in enumerate(history):
            x = 30 + i * (220 / (len(history) - 1))
            y = 60 - (float(a.sensory_score) - low) / (high - low) * 44
            points.append({"x": round(x, 1), "y": round(y, 1), "label": f"{a.analysis_date.strftime('%d/%m')} · {_format_decimal_br(a.sensory_score, 1)}"})
    delta = (float(analysis.sensory_score) - float(previous.sensory_score)) if previous and analysis.sensory_score is not None and previous.sensory_score is not None else None
    return templates.TemplateResponse("classification_detail.html", _base_context(
        request, user, csrf_token, "coffee_classification", _repo=repo, title="Análise do lote",
        cd=_analysis_view(analysis), cd_harvest=harvest, cd_code=_lot_display_code(harvest),
        cd_versions=[{"id": a.id, "label": f"{a.analysis_date.strftime('%d/%m')} · {a.evaluator or 'sem responsável'}",
                      "on": a.id == analysis.id, "latest": i == 0} for i, a in enumerate(versions)],
        cd_delta=delta, cd_available=available, cd_points=points,
        cd_polyline=" ".join(f"{p['x']},{p['y']}" for p in points),
        cd_price_refs=_quality_price_refs(db, list(harvests.values()), by_lot),
        cd_can_sell=available > 0 and harvest_matches_season(harvest, scope.get("active_season")),
    ))


